insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$unikatni-pripravek-ode-mne-pro-vas-s-laskou$q$,$q$Unikátní přípravek ode mne pro vás. S láskou!$q$,$q$Prevence. Toto slovo zní napříč věkovými skupinami, bez rozdílu, jestli se jedná o muže, ženy či děti. Poslední měsíce a roky nás všechny hodně prověřily. Ukázaly nám zejména to, jestli jsme se v předchozích letech o sebe, o své tělo dostatečně starali, jestli náš imunitní systém a vše co s ním souv$q$,$q$<p><strong>Prevence.</strong> Toto slovo zní napříč věkovými skupinami, bez rozdílu, jestli se jedná o muže, ženy či děti. <strong>Poslední měsíce a roky nás všechny hodně prověřily. </strong>Ukázaly nám zejména to, jestli jsme se v předchozích letech o sebe, o své tělo dostatečně starali, jestli náš <strong>imunitní systém</strong> a vše co s ním souvisí pracují dobře.</p>
<p>Vyvinula jsem recepturu na jedinečný přípravek pro prevenci, ale i jako doplněk nastavené přírodní léčby. Přírodní kapsle Multiserafin s vitamínem D</p>
<h3>Říkáte si, že na trhu je mnoho multivitaminů? Ano, ale ne tak unikátní jako je tento!</h3>
<p>Multiserafin je totiž z velké části sestaven z <strong>extraktů z plodů rostlin</strong>. Tyto extrakty obsahují velké množství <strong>přírodních bioaktivních látek.</strong> Bioaktivní látky jsou přirozeně přítomné v plodech a v rostlinách a jsou v nich vázané na další aktivní látky.<strong> Dobře účinkují pouze společně</strong>, tedy jen jako daný plod či rostlina. Jakákoliv jejich separace či technologická úprava zejména rafinace velmi snižuje účinky.</p>
<p><strong>Bioaktivní látky jsou nejkvalitnějším zdrojem přírodních vitamínů a minerálů</strong>. Mají výrazné <strong>protizánětlivé účinky</strong> a celkově aktivují všechny přirozené funkce v celém organismu. Působí nejen na <strong>imunitní systém</strong>, ale i na základní metabolické orgány jako jsou<strong> játra, slinivka, ledviny a střeva</strong>. Bioaktivní látky přirozeným způsobem <strong>harmonizují všechny žlázy s vnitřní sekrecí</strong> a také celý <strong>kardiovaskulární systém</strong>.</p>
<p><strong>Všechny ingredience v přípravku Multiserafin působí synergicky.</strong> To znamená, že vzájemně posilují svůj účinek, vstřebatelnost a využitelnost.</p>

<h3>Unikátní složka přípravku &#8211; Butyrát</h3>
<p>Právě pro vyšší vstřebatelnost bioaktivních látek obsahuje přípravek Multiserafin jedinečnou přísadu, a tou je Butyrát.</p>
<p>Butyrát je sůl kyseliny máselné, která by měla být v našich střevech obsažena přirozeně díky <strong>prospěšným střevním bakteriím.</strong> Těch je však u většiny populace nedostatek, a tak ve dobré <strong>butyrát dodávat jinou cestou.</strong></p>
<p>Butyrát <strong>podporuje těsná spojení střevního epitelu</strong>, a tím pomáhá zajišťovat bariérovou funkci střeva v obraně před patogeny a také napomáhá při jeho vstřebávacích funkcích. <strong>Butyrát eliminuje tzv. syndrom zvýšené propustnosti střev</strong>, za kterým stojí řada onemocnění jako jsou:</p>
<p>&#8211;          Chronické záněty močového měchýře</p>
<p>&#8211;          Alergie</p>
<p>&#8211;          Chronické ženské záněty</p>
<p>&#8211;          Záněty prostaty</p>
<p>&#8211;          Poruchy imunity</p>

<h3>Multiserafin obsahuje celé spektrum vitamínů a minerálů a také tolik chybějící vitamín D.</h3>
<p>Přírodní kapsle Multiserafin jsou vhodné pro každého, a to jako prevence, ale i jako doplněk k již nastavené léčby s bylinami či dalšími přírodními přípravky. Již nemusíte užívat další doplňující vitamíny a minerály!</p>
<p>Přírodní kapsle Multiserafin přesně zapadají do celého <strong>konceptu SERAFIN</strong>. <strong>Mohou se kombinovat se všemi výrobky</strong>, které pod touto značkou najdete.</p>
<p>Přírodní kapsle Multiserafin mohou užívat děti již od 3 let.</p>
<h3>Jaké jsou indikace přírodních kapslí Multiserafin?</h3>
<p>&#8211;          Podpora přirozené imunity</p>
<p>&#8211;          Chronické záněty</p>
<p>&#8211;          Anémie</p>
<p>&#8211;          Alergie</p>
<p>&#8211;          Podpora jater a ledvin</p>
<p>&#8211;          Únava</p>
<p>&#8211;          Stres</p>
<p>&#8211;          Chronické záněty střev</p>
<p>&#8211;          Akné a zánětlivé kožní problémy</p>
<p>&#8211;          Diabetes</p>
<p>&#8211;          Problémy s klouby</p>
<p>&#8211;          Neplodnost</p>
<p>&#8211;          Kandidózy</p>
<p>&#8211;          Překyselení</p>
<p>&#8211;          Bolesti hlavy</p>
<p>&#8211;          Problémy se štítnou žlázou</p>
<p>&#8211;          Problémy s vlasy a nehty</p>
<p>Přírodní kapsle Multiserafin by rozhodně neměly chybět v žádné domácnosti, kde lidem záleží na zdraví jejich a všech blízkých</p>
<p>koupíte<a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109"> zde</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2020/11/multiserafin.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2022-11-08T12:24:53+00:00$q$,$q$https://anetabenediktova.cz/unikatni-pripravek-ode-mne-pro-vas-s-laskou/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$adaptace-je-zakladem-radostneho-ziti$q$,$q$Adaptace je základem radostného žití$q$,$q$Už jsem na tomto světě „nějaký ten pátek“ a myslím si, že jsem ve svém životě zažila mnoho věcí a životních událostí. Nicméně doba, kterou procházíme v posledních několika letech se zdá být čím dál tím více náročnější. Většina lidí si myslela, že odezněním „covidové pandemie“ se vše uklidní, ale opa$q$,$q$<p>Už jsem na tomto světě „nějaký ten pátek“ a myslím si, že jsem ve svém životě zažila mnoho věcí a životních událostí. Nicméně doba, kterou procházíme v posledních několika letech se zdá být čím dál tím více náročnější.</p>
<p>Většina lidí si myslela, že odezněním „covidové pandemie“ se vše uklidní, ale opak je pravdou. <strong>Světové události gradují</strong> a vše se začíná velmi <strong>intenzivně odrážet</strong> na našich životech a primárně na <strong>naší vnitřní psychice.</strong></p>
<p>Výsledkem jsou přeplněné <strong>ordinace psychologů a psychiatrů</strong>. Bohužel se tato psychická zátěž a neschopnost vyrovnat se se změnami životních podmínek začíná nejvíce dotýkat <strong>mladé generace</strong>, která povětšinu nezažila velký nedostatek a životní krize.</p>
<p>V průběhu posledních desetiletí jsme žili vcelku pohodový život více méně v hojnosti. Nebyli jsme tolik vystavování překážkám a zkouškám jako předchozí generace. To v nás <strong>snížilo ostražitost a schopnost se přirozeně adaptovat</strong> na zhoršené životní podmínky.</p>
<p>Myslím si, že začíná být jasné, že už se nikdy nevrátíme do časů před rokem 2020.</p>
<h2>Začala nová etapa života a je potřeba se na ní adaptovat</h2>
<p>Proč? Protože, pokud se nezvládneme adaptovat, tak prostě z tohoto světa odejdeme. Zdá se vám toto tvrzení tvrdé? Není! Podívejte se ve svém okolí kolika lidem <strong>selhává imunitní systém</strong>, kolik lidí trpí <strong>autoimunitními chorobami</strong> kloubů, štítné žlázy střev…</p>
<p>Kolik lidí trpí <strong>únavou, nespavostí</strong>, kolika lidem vyrůstají různé typy <strong>novotvarů</strong> v těle a nemluvě o záplavě osob trpícími různými formami <strong>trávicích obtíží</strong>.</p>
<p>To vše je <strong>následek neschopnosti přirozené adaptace</strong> na změněné životní podmínky a z toho vycházející velký stres, který blokuje přirozené fungování našeho těla a zejména imunitního systému.</p>
<h2>Co s tím?</h2>
<p>V první řadě je nutné si uvědomit, že opravdu žijeme v jiných časech a <strong>tuto skutečnost přijmout.</strong> Následně pak pravidelně dělat <strong>opatření</strong>, která mi pomohou k lepší adaptaci na nové podmínky.</p>
<ol>
<li><strong>Podívejte se na lidi kolem sebe</strong> a zamyslete se nad tím, kdo z nich svojí přítomností vás <strong>„nabíjí“</strong> a kdo naopak vám vaší <strong>energii ubírá</strong>. Zkuste eliminovat setkávání a konverzaci s nimi. Obklopujte se jen osobami, které nemají tendenci na vše nadávat, vyhledávat jen problémy a komplikace. Je možné, že o většinu „přátel“ přijdete, ale umožníte tak vstup do vašeho prostoru těm novým, pozitivním</li>
<li>Stejným drobnohledem se <strong>podívejte na sebe, na svoje myšlenky a slova</strong>. Jsou pozitivní, nabíjející? Nebo vaše slova obsahují převážně negativní věci? <strong>Pozorujte to a vědomě měňte</strong>. Pokud se přistihnete, jak rozebíráte negativní věci<strong> vědomě svůj tok myšlenek a slov změňte.</strong> Tak si postupně ve svém mozku vybudujete jiný návyk. Návyk na hezké pozitivní myšlení a mluvu.</li>
<li><strong>Pozorujte, co jíte</strong>. Jídlo je palivo, energie, na kterou naše tělo funguje. Alkohol, cukry, konzervační soli, dochucovací soli, přemíra kravského mléka, přemíra lepku. To vše oslabuje naše tělo, střeva, imunitu a psychiku. Cíleně zařazujte do svého jídelníčku co <strong>nejvíce čerstvé zeleniny</strong>.</li>
<li><strong>Hýbejte se!</strong> Pohyb je zdrojem dobré nálady, jelikož podněcuje přirozenou tvorbu „hormonů dobré nálady“. Nemusíte vydávat žádné heroické sportovní výkony. Stačí přirozená chůze. Zkuste se denně projít v parku či v lese. <strong>Víte, že existuje pojem „lesní medicína“?</strong> Je to medicínský obor, který je v Japonsku velmi uznávaný a praktikovaný. V rámci tohoto oboru jsou vědecky prokázané pozitivní účinky stromů a celého lesa na náš imunitní systém a psychiku.</li>
<li><strong>Nesledujte zprávy</strong> v televizi, novinách či na internetu. Říkám tomu „odpojit se od metrixu“. Toto odpojení je velmi osvobozující. První dny jsou těžké, jelikož už většina z nás má návyk na to sledovat telefon a v něm různé stránky a sociální sítě. Můžete zažívat i něco podobného jako jsou abstinenční příznaky u odkývání na alkohol či omamné látky. Nicméně po několika dnech můžete pozorovat velkou úlevu a uklidnění.</li>
<li><strong>Čtěte knihy!</strong> Najděte si pozitivní, motivující literaturu a prostě čtěte. A pokud to bude literatura s návody jak pracovat se sebou a se svojí psychikou, tak je důležité tyto návody si <strong>přečíst, ale také i zkoušet, praktikovat.</strong></li>
<li>Naučte se jednoduché <strong>techniky práce se svoji myslí</strong> a podvědomím. Čím jsou jednodušší, tím jsou účinnější. Zkuste třeba některé z youtube kanálu <a href="https://www.youtube.com/c/lajprik">Martina Lajprika.</a></li>
<li><strong>Využívejte dary přírody!</strong> Farmaceutický průmysl nám nabízí celou řadu tabletek na lepší, a ještě lepší náladu. V první fázi nám opravdu mohou významně ulevit a jsou situace, kdy je potřeba je využít. Dlouhodobé <strong>užívání těchto farmak však vede k rozvoji další vedlejších nemocí</strong> a nepřináší řešení původního problému. Příroda poskytuje celou řadu přírodních látek, které nám umí významně pomoci při velkém psychickém zatížení.</li>
</ol>
<h2>Dary matky přírody</h2>
<h3><a href="https://serafinbyliny.cz/produkt/stesti_742">Mucuna pruriens </a></h3>
<p>Říká se jí také sametová fazole. Je to popínavá liána jejíž plodem jsou lusky zabalené do jemných chloupků. Plody se pro svůj velký obsah léčivých látek používají v tradičních medicínách již celá staletí.</p>
<p><strong>Významnou látkou je zejména l-dopa,</strong> což je přírodní látka podporující přirozenou tvorbu dopaminu v našem těle.<strong> Dopamin</strong> je hormon, který má významný <strong>vliv na naši psychiku, na pocit štěstí a radosti.</strong> Dopamin nám umožňuje prožívat pocity uspokojení, potěšení, umožňuje nám se dobře učit, pohybovat se i usínat.  Dopamin mimo jiné harmonizuje hladinu prolaktinu v krvi, harmonizuje i ostatní pohlavní hormony jak u žen tak i u mužů.</p>
<p>L-dopa významně snižuje projevy nemoci u pacientů s <strong>Parkinsonovou chorobou.</strong></p>
<h3><a href="https://serafinbyliny.cz/produkt/pohoda_126">Kudzu Vine</a></h3>
<p>Latinským názvem Pueraria lobata, je divoce rostoucí rostlinou vyskytující se v Asii, ale rovněž v severní Americe.</p>
<p><strong>Kudzu podporuje přirozenou produkci serotoninu v organismu</strong>. Serotonin je hormon, který <strong>reguluje naši náladu</strong>. Působí jako neurotransmiter, tedy přenašeč vzruchů v nervové tkáni. To ale není jeho jediná funkce.</p>
<p>Serotonin ovlivňuje celou řadu orgánů v našem těle, a to od <strong>krevního řečiště přes svalový tonus až po emocionální stavy</strong>. Serotonin působí i na náš <strong>trávicí trakt</strong>. Při jeho nedostatku trpíme poruchami trávení způsobenými vlivem stresu.</p>
<p>Serotonin je produkován v našem mozku, ale jen v malém množství. V daleko větším množství pak ve <a href="https://anetabenediktova.cz/propustne-strevo-je-riziko-nemoci/">střevech</a>.</p>
<p>Serotonin potřebuje pro své účinkování v těle pomocné látky, tzv. prekurzory. Jedním z nich je aminokyselina zvaná L-Tryptofan, kterou můžeme snadno získávat jak ze stravy, tak z potravinových doplňků.</p>
<blockquote>
<p><strong>Dostatečné množství  serotoninu a dopaminu v oběhovém ústrojí, nám pomáhá stabilizovat nervový systém, což přináší posílení dobré nálady, sebevědomí, efekt uspokojení, překonání fobií a zvýšení odvahy a adaptability.</strong></p>
</blockquote>
<h2>Můj tip</h2>
<p>popisované byliny najdete v kapslích<a href="https://serafinbyliny.cz/produkt/pohoda_126"> Pohoda</a> a <a href="https://serafinbyliny.cz/produkt/stesti_742">Štěstí</a>. Tyto kapsle je možné užívat současně a popřípadě je doplnit čajem<a href="https://serafinbyliny.cz/produkt/antistres-porcovany-caj_404"> Antistres</a>. Tato kombinace podpoří vaše <strong>zvládání stresu a adaptabilitu</strong>. Zlepší vaši <strong>náladu, zmírní projevy stresu a zkvalitní spánek.</strong></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/11/pocasi-a-adaptogeny.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-11-01T09:41:19+00:00$q$,$q$https://anetabenediktova.cz/adaptace-je-zakladem-radostneho-ziti/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$jak-lecit-nachlazeni-chripku-a-covid$q$,$q$Jak léčit nachlazení, chřipku a covid$q$,$q$Chřipka, nachlazení či covid? Vše má podobné příznaky, ale neléčená chřipka či neléčené projevy covidu mohou mít fatální následky. Těmi často jsou chronické bolesti kloubů, poškození srdce a cév, změny na plicích a průduškách, psychické změny, nespavost. To jsou jen některé z nich. Mějte rádi sebe a$q$,$q$<p>Chřipka, nachlazení či covid? Vše má podobné příznaky, ale <strong>neléčená chřipka</strong> <strong>či neléčené projevy covidu mohou mít fatální následky</strong>.</p>
<p>Těmi často jsou <strong>chronické bolesti kloubů, poškození srdce a cév, změny na plicích a průduškách, psychické změny, nespavost</strong>. To jsou jen některé z nich. Mějte rádi sebe a své tělo a dopřejte mu klidné a pohodové uzdravení. Odvděčí se vám!</p>
<h2><strong>Jaký je mezi nimi rozdíl?</strong></h2>
<p><strong>Nachlazení</strong> je rozhodně <strong>mírnější</strong> onemocnění než chřipka či covid. Při nachlazení se můžete cítit špatně nanejvýš pár dní, při chřipce nebo covidu se budete cítit velmi špatně po dobu několika dnů až týdnů. Nachlazení má mírnější průběh s mírně zvýšenou teplotou, vodnatou až mírně zabarvenou rýmou.</p>
<p><strong>Covid</strong> je způsobovaný podobnými mutujícími viry jako <strong>klasická chřipka,</strong> na kterou jsme byli léta zvyklí.  Typickými příznaky chřipky bývají vysoké teploty, bolesti svalů, v krku, hlavy, kašel, rýma někdy zvracení. Může také způsobit závažnější zdravotní problémy jako je třeba zápal plic.</p>
<p>U onemocnění <a href="https://anetabenediktova.cz/post-covid-syndrom/"><strong>covid</strong></a> a většiny jeho mutací jsou příznaky podobné jako u silnější chřipky, ale jsou daleko intenzivnější a podle zkušeností zde bývají často ohrožená i játra, ledviny a cévy.</p>
<p>Původcem obou onemocnění jsou <strong>viry</strong>. V současné době již víme, že antibiotická léčba na viry není účinná, proto se v medicíně používají různé typy antivirotik, a to zejména u těžších stavů chřipky a u těžších stavů covidu. <strong>Celkově je však léčba spíše symptomatická, tedy léčba zmírňující projevy jako je třeba vysoká teplota či urputný kašel.</strong></p>
<h2><strong>Prvním krokem léčby je prevence</strong></h2>
<p>Chřipková onemocnění se opakují v různých vlnách každým rokem. Mezi takové typy chřipkových onemocnění se již řadí i onemocnění covidem v nějaké z jeho forem.</p>
<p>V rámci prevence a<strong> posílení imunitního systému</strong> je důležitá <strong>strava</strong> bohatá na vitamíny a minerály, která je z co nejvíce přirozených surovin s minimem přidaných chemických dochucovadel, konzervantů, solí a cukru.</p>
<p>Důležitý je <strong>pravidelný pohyb</strong> ideálně na čerstvém vzduchu, který přináší přirozené otužování, vyplavování „hormonů dobré nálady“ a taky přirozený zdroj vitamínu D ze slunečního záření.</p>
<p><strong>Byliny</strong> zde mají své velké opodstatnění. Uplatňují se velmi dobře plody <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109"><strong>rakytníku</strong></a>, šípky, <strong><a href="https://serafinbyliny.cz/produkt/echinacea-tinktura-z-bylin_358">echinacea,</a></strong> květy <a href="https://serafinbyliny.cz/produkt/divizna-tinktura-z-pupenu_1"><strong>divizny</strong></a> nebo extrakt z <a href="https://serafinbyliny.cz/produkt/cecko-serafin_113"><strong>camu camu</strong></a> jako přirozený zdroj vitamínu C.</p>
<h2><strong>A co dělat, pokud přeci jen onemocníme?</strong></h2>
<p><strong> </strong>Při <strong>těžkém průběhu</strong> všech onemocnění je nutné se <strong>obrátit na lékaře</strong>. Při běžném průběhu nachlazení, chřipky i covidu je léčbě hlavně <strong>symptomatická</strong>.</p>
<h3>Prvním příznakem bývá nejčastěji <strong>horečka</strong></h3>
<p>Důležité je vědět, že tělesná teplota do 38 má pozitivní efekt pro organismus, pomáhá totiž imunitnímu systému „zabíjet“ viry. Nebojte se tedy, a pokuste se horečku v první fázi snížit <strong>zábal</strong>y.</p>
<p>Namočte osušku anebo prostěradlo do studené vody, vyždímejte jej a obalte si s ním celé tělo od podpaží dolů. Na to dejte deku, lehněte si do postele a přikryjte se.</p>
<p><strong>Důležité je dodržovat pitný režim. </strong>Popíjejte bylinné čaje s obsahem bylin, které účinně snižují teplotu. Hlavním zástupcem těchto bylin je kůra <a href="https://serafinbyliny.cz/produkt/nastydnuti-sypany-caj_208"><strong>Vrby bílé</strong> </a>a také nať <a href="https://serafinbyliny.cz/produkt/tuzebnik-tinktura-z-pupenu_191"><strong>Tužebníku jilmového,</strong></a> ze kterého se dříve vyráběl aspirin. Skvěle pomáhá i květ <a href="https://serafinbyliny.cz/produkt/nastydnuti-sypany-caj_208"><strong>Lípy srdčité</strong> </a>nebo květ Černého bezu</p>
<p>Při léčbě virových onemocnění se velmi osvědčila tinktura <a href="https://serafinbyliny.cz/produkt/lichorerisnice-tinktura-z-pupenu_177"><strong>z pupenů Lichořeřišnice</strong></a> a semen <strong><a href="https://serafinbyliny.cz/produkt/grep-tinktura-z-bylin_361">Grapefruitu.</a></strong></p>
<p>Obě mají silné antivirotické a antibiotické působení. Doporučené dávkování při akutním onemocnění je: <strong>10 kapek od každé tinktury užívat každé 4 hodiny</strong>, a to první a druhý den onemocnění, dále pak dle dávkování.</p>
<p><strong>Silnou zbraní</strong>, která funguje při silné chřipce nebo covidu je léčivá houba <a href="https://anetabenediktova.cz/coriolus-zazrak-z-lesa/"><strong>Coriolus</strong></a> a také míza z pralesního stromu zvaná <a href="https://anetabenediktova.cz/draci-krev-amazonsky-zazrak-pro-vas/"><strong>Dračí krev</strong></a>. Oba tyto přírodní přípravky jsou velmi účinné a fungují rychle nejenom na zvýšenou teplotu, ale zejména cíleně na viry, způsobující chřipková onemocnění.</p>
<h3>Co když hodně kašlu?</h3>
<p><strong>Kašel </strong>může být dalším průvodním symptomem, a to <strong>zejména u covidu</strong>. Úporný, dráždivý kašel dokáže zastavit<a href="https://serafinbyliny.cz/produkt/jitrocelovy-sirup_696"><strong> jitrocelový sirup</strong> </a>a dlouhodobě na něj velmi dobře působí další léčivá houba, a tou je <strong><a href="https://anetabenediktova.cz/agaricus-bozi-houba/">Agaricus</a></strong>.</p>
<p><a href="https://anetabenediktova.cz/agaricus-bozi-houba/"><strong>Agaricus</strong> </a>je možné užívat jak v akutní fázi nemoci, tak i na doléčení a snížení následků chřipky a covidu.</p>
<h3><strong>Bolest hlavy</strong></h3>
<p>Při bolestech hlavy je vynikající <strong>inhalace:</strong></p>
<p>V hrnci s vodou mírně 3 minuty povaříme <strong>květ černého bezu, nakrájený česnek a nadrcený kmín.</strong></p>
<p>Odstavíme a necháme lehce vychladnout a pak se nad tuto teplou lázeň nakloníme s ručníkem přehozeným přes hlavu a vdechujte odpařující se látky nosem. Zvolte správnou teplotu odvaru, ať se neopaříte. Po takto provedené inhalaci se dýchací cesty uvolní a uvolní se tlak v oblasti čelních dutin.</p>
<h3>A co víc?</h3>
<p>Při léčbě nachlazení, chřipky i covidu je velmi důležité <strong>dodržovat klid na lůžku</strong>, odpočívat a nechat svému tělu možnost se uzdravit. Zejména neléčený nebo špatně léčený covid může v budoucnu přinášet tzv. <a href="https://anetabenediktova.cz/post-covid-syndrom/">post covid syndrom</a> s jeho celou škálou projevů jako je <a href="https://anetabenediktova.cz/padani-vlasu-po-covidu/">padání vlasů</a> nebo<a href="https://anetabenediktova.cz/borelioza-ci-post-covid-syndrom/"> bolesti kloubů.</a></p>
<p>Jelikož se jedná o velmi infekční onemocnění, tak určitě není přínosné chodit s příznaky nachlazení do práce, do kolektivu a ohrožovat nákazou další osoby.</p>
<p>Dopřejte svému tělu láskyplnou léčbu klid a odpočinek. Potom budete mít dostatek sil na prožívání radostí a krás života.</p>

<blockquote>
<p><strong>Moje tipy</strong></p>
<p><strong>Nachlazení:</strong> čaj Nastydnutí + tinktura z pupenů Lichořeřišnice + tinktura Grep</p>
<p><strong>Chřipka:</strong> čaj Nastydnutí + Dračí krev + tinktura Grep</p>
<p><strong>Covid akutní fáze:</strong> čaj Imunita střídat s čaje Průdušky + Coriolus + kapsle Plíce</p>
<p>(s Agaricusem)</p>
</blockquote>
<p>vše najdete na<a href="https://serafinbyliny.cz/"> www.serafinbyliny.cz</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/10/DUTINY.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-10-09T20:12:01+00:00$q$,$q$https://anetabenediktova.cz/jak-lecit-nachlazeni-chripku-a-covid/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$rijen-podporujeme-zaludek-a-traveni$q$,$q$Říjen – podporujeme žaludek a trávení$q$,$q$Jídlo nám přináší nejenom základní nutnou výživu, ale často také radost. Dokáže vyvolat příjemné pocity. V říjnu je podle pravidel čínského pentagramu nejvíce ohrožen žaludek. Úloha žaludku v našem organismu Jedním ze základních orgánů trávicí soustavy je žaludek. Žaludek svým tvarem připomíná vak a$q$,$q$<p>Jídlo nám přináší nejenom základní nutnou výživu, ale často také radost. Dokáže vyvolat příjemné pocity. <strong>V říjnu</strong> je podle pravidel čínského pentagramu nejvíce <strong>ohrožen žaludek.</strong></p>
<h3>Úloha žaludku v našem organismu</h3>
<p>Jedním ze základních orgánů trávicí soustavy je žaludek. Žaludek svým tvarem připomíná vak a navazuje v trávicí soustavě na jícen.</p>
<p>Žaludek shromažďuje potravu a rozmělněnou ji tráví pomocí <strong>kyseliny chlorovodíkové a enzymů</strong>. Kyselé prostředí v žaludku funguje jako <strong>ochranný štít před vniknutím nežádoucích bakterií</strong> a jiných mikroorganismů.</p>
<p>Smršťováním a uvolňováním svalů ve stěně žaludku se jeho obsah mísí s trávicími šťávami. Vzniká trávenina, která se posunuje dále do dvanáctníku a tenkého střeva.</p>
<h3>Nejčastější onemocnění</h3>
<p>Podzimní období často přináší opakující se problémy s trávicím traktem. Nejčastěji to bývá <strong>nadýmání, žaludeční vředy a také reflux jícnu.</strong></p>
<h4>Reflux jícnu</h4>
<p>Při refluxu jícnu postupně dochází k uvolnění dolního svěrače jícnu, který se nachází na přechodu mezi žaludkem a jícnem. Následkem toho začne pronikat kyselý obsah žaludku do oblasti jícnu.</p>
<p>Žaludeční kyseliny, zejména kyselina chlorovodíková, postupně poškozují sliznici jícnu, což lidé vnímají jako <strong>pálení žáhy, říhání, pálení za hrudní kostí.</strong> V některých případech mohou příznaky vypadat jako <strong>infarkt myokardu.</strong></p>
<p>Pronikající žaludeční kyseliny také často způsobují <strong><a href="https://anetabenediktova.cz/kasel-jeden-priznak-vice-nemoci/">chronický kašel</a>,</strong> který nereaguje na klasickou léčbu léky proti kašli. V tomto případě je vždy vhodné zamyslet se nad tím, jestli není kašel průduškový, ale je způsobený trvalým podrážděním jícnu a hltanu žaludečními kyselinami.</p>
<p>Důvodem vzniku refluxu jícnu je v převážné většině <strong>nesprávná skladba stravy</strong>, zejména strava obsahující velké množství přepálených tuků, koření, alkoholu a cukru. Častým důvodem bývá i dlouhodobý <strong>chronický stres.</strong> Reflux jícnu také vzniká, pokud dlouhodobě jíme jednorázově velký objem stravy najednou, a ten pak roztahuje žaludek a tlačí na okolní orgány.</p>
<blockquote>
<p><strong>Můj tip</strong> &#8211;  střídejte po dni čaje <a href="https://www.serafinbyliny.cz/produkty-zaludek-a-dvanacternik-bylinny-caj-porcovany-detail-1614">Žaludek a dvanácterník</a> a <a href="https://serafinbyliny.cz/produkt/jicen-sypany-caj_684">Jícen</a>. K tomu denně užívejte kapsle <a href="https://www.serafinbyliny.cz/produkty-digestiv-prirodni-kapsle-detail-1257">Digestiv</a> po jídle a <a href="https://serafinbyliny.cz/produkt/imunofungin-bio_456">IMUNOfungin BIO</a> s obsahem Čagy sibiřské na lačno. Při stresu můžete přidat kapsle <a href="https://serafinbyliny.cz/produkt/pohoda_126">Pohoda</a></p>
</blockquote>
<h4>Žaludeční vředy, <strong>Helicobacter pylori</strong></h4>
<p>Žaludeční vředy je zánětlivé onemocnění žaludku, při kterém dochází k <strong>poškození žaludeční sliznice</strong> působením kyseliny chlorovodíkové z žaludeční šťávy. Za normálních okolností je sliznice žaludku chráněna zejména vrstvou hlenu, pokud dojde k poškození ochranné vrstvy, může dojít k poškození sliznice.</p>
<p>Sliznici nejčastěji poškozuje infekce bakterií <strong>Helicobacter pylori.</strong> K rozvoji tohoto onemocnění dále přispívá<strong> kouření, alkohol, stres a nevhodná strava</strong>.</p>
<blockquote>
<p><strong>Můj tip:</strong> pijte čaj čaj <a href="https://www.serafinbyliny.cz/produkty-zaludek-a-dvanacternik-bylinny-caj-porcovany-detail-1614">Žaludek a dvanácterník</a>. K tomu denně užívejte  tinkturu <a href="https://www.serafinbyliny.cz/produkty-grep-tinktura-z-bylin-detail-227">Grep</a> + <a href="https://www.serafinbyliny.cz/produkty-draci-krev-detail-11826">kapky Dračí krev </a></p>
</blockquote>
<h3>Jakou zvolit stravu</h3>
<p>Při léčbě i při prevenci onemocnění žaludku hraje zásadní roli strava. Jídlo je důležité upravit si tak, aby obsahovalo co nejméně kombinací, které nejvíce zatěžují žaludek, jícen a další orgány trávicího traktu. Nejvíce zatěžující kombinace je <strong>cukr+mouka+kypřidlo = pečivo a sladké pečivo.</strong></p>
<p>V případě je nutné striktně číst složení. Většina celozrnných výrobků, které se tváří zdravě, moc zdravé být nemusí. Správné celozrnné pečivo je upečené z celozrnné žitné mouky. Je jedno, jestli tam jsou přidaná semínka na chuť nebo na ozdobu, celozrnné = celozrnná mouka. Mouka, která není vymílaná a obsahuje obal ze zrna.</p>
<p>Bohužel na trhu většinou dostanete pečivo, které je z více než 60 % upečené z bílé pšeničné mouky, zbytek je žitná mouka a zrníčka. Často bývá dobarvované melasou.</p>
<p><strong>Nejhorší varianta jsou rozpeky ze zmrazeného polotovaru</strong>. Tyto rozpeky se dováží ze zahraničí a velmi často obsahují plísně. Plísně zmrazením nezničíte!</p>
<p>Nejlepší variantou je čerstvě upečený <strong>žitný kváskový chléb</strong>, který obsahuje pouze celozrnnou žitnou mouku.</p>
<p>Obecně jsme v našich zeměpisných šířkách zvyklí jíst velké množství pečiva, což při našem životním stylu, kdy převážná většina osob má sedavé zaměstnání, vůbec není vhodné.</p>
<h3>Barvy nám pomáhají</h3>
<p>Podle pravidel čínské medicíny má každý orgán svoji barvu, která jej dokáže léčit. Žaludek podporuje <strong>barva žlutá a všechny její odstíny</strong>. Touto barvou se obklopujte, volte ji na oblečení a také noste drahé kameny této barvy jako je třeba citrín nebo jaspis.</p>
<p>I jídlo zkuste ladit do této barvy. <strong>Typickým pokrmem podzimu jsou dýně</strong> ve všech svých odstínech žluté a oranžové barvy a se všemi svými úžasnými chutěmi. Dýně mimo jiné působí i velmi dobře na snížení překyselení žaludku a dodá tělu velké množství vitamínů, minerálů a dalších živin.</p>
<p>Máte-li chronické potíže se žaludkem, zkuste se zamyslet i nad tím, co nebo kdo vám „leží v žaludku“. Každá nemoc má svůj citový – psychický základ. Uzdravte duši a uzdraví se vám tělo.</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2020/10/zaludek-2.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-10-03T06:12:45+00:00$q$,$q$https://anetabenediktova.cz/rijen-podporujeme-zaludek-a-traveni/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$dna-a-kyselina-mocova$q$,$q$Dna a kyselina močová$q$,$q$Dna bývala považována za nemoc králů a šlechty. S ohledem na velký nárůst pacientů s vysokou hladinou kyseliny močové v krvi a s onemocněním dna lze říci, že přes všechny peripetie se máme velmi dobře. Prostě si žijeme jako králové… Projevy U onemocnění dnou jde o ukládání či krystalizaci krystalků $q$,$q$<p>Dna bývala považována za nemoc králů a šlechty. S ohledem na velký nárůst pacientů s vysokou hladinou kyseliny močové v krvi a s onemocněním dna lze říci, že přes všechny peripetie se máme velmi dobře. Prostě si žijeme jako králové&#8230;</p>
<h2>Projevy</h2>
<p>U onemocnění dnou jde o ukládání či krystalizaci krystalků kyseliny močové v kloubech. Krystalky <b>kyseliny močové</b> v kloubech připomínají dlouhé jehlice a vyvolávají <b>poranění provázené akutním zánětem</b>. Známkami zánětu jsou <b>otok, zarudnutí, zvýšení teploty, bolestivost</b> .</p>
<p>Nejčastěji dochází k prudkému zánětu kloubu u <b>palce nohy,</b> a to převážně v noci, během spánku.<b> Bolest v kloubu</b> bývá často popisována jako největší bolest, jakou je člověk schopen zažít.</p>
<p>Dna je typicky provázena <b>vysokou hladinou kyseliny močové v krvi</b>, ale také v moči. Zvýšená hladina kyseliny močové může být spojena s mnoha nemocemi.</p>
<h2>Příčiny</h2>
<p>Přestože neznáme všechny faktory ovlivňující krystalizaci kyseliny močové, víme, že se na tom z velké části podílí fenomén <b>chronického <a href="https://serafinbyliny.cz/magazin/prekyseleni-tela-projevy-a-dusledky_63" target="_blank" rel="noopener">překyselení organismu</a></b>. Další příčinou může být i dlouhodobý chronický stres, který silně oslabuje funkce ledvin, a tím i vylučování kyseliny močové z těla. Syndrom <a href="https://anetabenediktova.cz/propustne-strevo-je-riziko-nemoci/">zvýšené propustnosti střev</a> se na této chorobě částečně také podílí.</p>
<p>Za<b> hlavní příčinu </b>dny je považována nevhodná životospráva, především <b>nadměrná konzumace masa, uzenin, alkoholu</b>, a to hlavně piva. Dnu mohou také vyvolat některé<b> léky na vysoký tlak a otoky</b>. Dna postihuje častěji muže než ženy.</p>
<p>Zvýšená hladina kyseliny močové může<b> poškozovat ledviny</b>, ale je důležité si uvědomit , že <b>oslabení ledvin</b> <b>může vést ke</b> <b>zvýšení hladiny kyseliny močové</b>, protože ta je ledvinami vylučována.</p>
<h2>Co s tím?</h2>
<p>Klasická léčba řeší toto onemocnění <b>primárně léky </b>na snížení koncentrace kyseliny močové v krvi. I tyto léky mají své <b>vedlejší účinky</b>, a to zejména na <b>funkce ledvin</b>. Někdy ale není zbytí a při velkých bolestech alespoň z počátku léčby je nutné na tuto alternativu přistoupit.</p>
<p>Ruku v ruce s tím však musí jít<b> úprava životního stylu, tedy zejména stravy</b>.</p>
<p><b>Škodlivépotraviny</b> –potraviny s vysokým obsahem purinů – maso, vnitřnosti, sardinky, uzeniny, sýry, čokoláda, kakaový prášek, luštěniny, alkohol, tavené sýry, bujóny a jiné dochucovací soli, slané chipsy a obecně omezit solení.</p>
<p><b>Podporující potraviny</b> – syrová zelenina a ovoce, zeleninové a ovocné šťávy ředěné vodou, celozrnná rýže, jáhly, pohanka, slzovka, kukuřice. Zelenina je samozřejmě vhodná i po tepelné úpravě, ale v akutním stavu více uleví syrová zelenina a zeleninové šťávy. Prostě všechny potraviny, které působí v organismu zásaditě. V tomto případě je to zejména kořenová zelenina jako je celer, mrkev a petržel.</p>
<p><b>Velmi důležitý je pitný režim</b>. Nezapomeňme, že kyselina močová se vyplavuje přes ledviny. V případě dnavého záchvatu je vhodné vypít minimálně <b>dva litry <a href="https://serafinbyliny.cz/produkt/rednavit-sypany-caj_220">bylinného čaje</a></b> podporujícího vylučování kyseliny močové a <b>k tomu filtrovanou vodu ideálně ochucenou citronem.</b></p>
<p>Pokud se tedy bavíme o kyselině močové a onemocnění dna, tak zde více než u jiných nemocí platí, že <b>dobrý životní styl nám může zajistit, že toto bolestivé onemocnění naše tělo nepostihne.</b></p>
<blockquote>
<p><strong>Můj tip při vysoké hladině kyseliny močové:</strong> Pijte čaj <a href="https://serafinbyliny.cz/produkt/rednavit-sypany-caj_220">Rednavit</a>, k tomu užívejte tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/tuzebnik-tinktura-z-pupenu_191">Tužebník</a> a kapsle <a href="https://serafinbyliny.cz/produkt/cordyceps_107">Cordyceps</a></p>
<p>Více o Tužebníku se dočtete <a href="https://anetabenediktova.cz/tuzebnik-jilmovy-prirodni-aspirin/">zde</a></p>
<p>Více o Cordycepsu se dočtete <a href="https://anetabenediktova.cz/cordyceps-houba-nebo-housenka/">zde</a></p></blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/09/kostival.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-09-28T16:26:25+00:00$q$,$q$https://anetabenediktova.cz/dna-a-kyselina-mocova/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$jak-na-bolestive-dasne-a-zuby-prirodni-cestou$q$,$q$Jak na bolestivé dásně a zuby přírodní cestou$q$,$q$Bolesti zubů a dásní patří k nejúpornějším bolestem v těle. Problémy se zuby a dásněmi mimo jiné znamenají i velmi ztíženou možnost přijímání a rozmělňování potravy, což následně přináší i obtíže s trávením, nadýmání bolesti břicha. Problémy s dásněmi se dají velmi dobře řešit přírodní cestou, ale j$q$,$q$<p>Bolesti zubů a dásní patří k<strong> nejúpornějším bolestem</strong> v těle. Problémy se zuby a dásněmi mimo jiné znamenají i velmi<strong> ztíženou možnost přijímání</strong> a rozmělňování potravy, což následně přináší i obtíže s trávením, <strong>nadýmání bolesti břicha</strong>.</p>
<p>Problémy s dásněmi se dají velmi dobře řešit přírodní cestou, ale je nutné začít včas!</p>
<h1>Zánět dásní</h1>
<p>Zánět dásní způsobují <strong>bakteriální infekce</strong>, které se tvoří na zubech a dásních. Jsou způsobeny zejména nedostatečnou zubní hygienou, v menší míře také dědičnými faktory. Bakterie však často pronikají ze <strong>skrytých vnitřních zánětů</strong> v těle krevním řečištěm ke kořenům zubů a do dásní, a tak začnou způsobovat chronické záněty.</p>
<p>Nejčastěji to bývají <strong>stafylokokové bakterie</strong>. Na vzniku zánětu dásní se mohou podílet také kouření, cukrovka, užívání léků či dlouhodobě překyselený organismus. Zánět dásní se může stát počátečním stádiem parodontózy.</p>
<p>Zánět se projevuje zčervenáním, podrážděním, otoky, mírnou bolestí. Dáseň je oteklá a křehká. Snadno se poraní a krvácí.</p>
<h3>Přírodní léčba zánětu dásní</h3>
<p>Při léčbě zánětu velmi dobře fungují <strong>byliny</strong>, které působí nejen <strong>protizánětlivě</strong>, ale také proti bakteriím a virů.</p>
<p>Typickým zástupcem je Čaga sibiřská obsažená v silně koncentrované formě v přípravku <a href="https://serafinbyliny.cz/produkt/imunofungin-bio_456">IMUNOfungin BIO.</a>  Tato parazitující <a href="https://anetabenediktova.cz/strazci-nasi-imunity-betaglukany-z-hub/">přírodní houba</a> hojí záněty sliznic a velmi účinně působí proti bakteriím.</p>
<p>Ve spojení s tinkturou z <a href="https://serafinbyliny.cz/produkt/grep-tinktura-z-bylin_361">Grepových jader</a> jsou účinnými <strong>bojovníky proti zánětu dásní.</strong> Oba přípravky je vhodné při užívání chvíli podržet v ústech, aby docházelo i lokálnímu působení.  Celou léčbu můžeme doplnit čajem <a href="https://serafinbyliny.cz/produkt/odkyseleni-organismu_453">Odkyselení organismu.</a></p>
<p>Při léčbě zánětu dásní je důležitá důsledná <strong>ústní hygiena</strong>, hlavně čištění zubů pomocí kartáčku a mezizubních kartáčků. Po vyčištění zubů, tedy po odstranění plaku, lze také použít speciální přírodní zubní pasty a ústní vody.</p>
<p>Neléčený zánět dásní se může rozvinout v parodontózu, která je příčinou úbytku kosti kotvící zuby a následně vede až k jejich ztrátě.</p>
<h1>Parodontóza</h1>
<p>Obávané a bolestivé postižení zubního aparátu. Vlastní příčina paradentózy vlastně spočívá v <strong>oslabení vazivových vláken</strong>, které zub kotví a spojují povrch zubu s kostí v oblasti kořene zubu a s dásní v oblasti krčku zubu. Tato vlákna tím, že pevně váží zub k dásni, zabraňují vniknutí bakterií, zbytků jídla či dalších škodlivých částic k povrchu zubu, který je ukryt v dásni a není chráněn sklovinou, jako jeho vyčnívající část.</p>
<h3>Důvody vzniku paradentózy</h3>
<p>Jsou jednoduché a stejně tak jednoduše se jim dá předcházet. Je to zejména <strong>špatná ústní hygiena</strong>, neřešená přítomnost <strong>zubního kamene</strong> nebo dráždění zubní dásně vystouplými (nebo zčásti odlomenými) <strong>zubními výplněmi</strong> neboli plombami.</p>
<p><strong>Prevence je jednoduchá</strong>. Pravidelně se věnovat <strong>čištění zubů</strong> a ústní hygieně vůbec a navštěvovat zubního lékaře.</p>
<p>Zuby si je třeba čistit dvakrát denně, pokaždé minimálně tři minuty. Také musíme věnovat pozornost hygieně mezizubních prostor. Pomocí speciálních kartáčků nebo zubních nití, které mohou vyčistit prostor mezi zuby a neporanit dásně. Důležité je dbát na správnou stravy s minimem přidaného cukru a s maximem ovoce a zejména zeleniny.</p>
<h3> Přírodní léčba parodontózy</h3>
<p>V každém případě věnovat pečlivou pozornost pravidelné ústní hygieně. Užíváním zubních past s obsahem bylin můžeme zabránit krvácení a většímu odhalování zubních krčků.</p>
<p>Z přírodních přípravků je vhodné užívat doplňky stravy s <strong>koenzymem Q10</strong>, který pomáhá zastavit krvácení dásní a přispívá ke zpevnění vazby zubů vazivovými vlákny k dásni.</p>
<p>Skvělým a velmi účinným přírodním lékem je <a href="https://anetabenediktova.cz/draci-krev-amazonsky-zazrak-pro-vas/">Dračí krev</a> ,která působí antibakteriálně a regeneruje pojivovou tkáň. K léčbě parodontózy už naši předkové s velkými úspěch používaly výtažek z <a href="https://serafinbyliny.cz/produkt/dub-tinktura-z-pupenu_159">Dubu letního.</a> Tinktura z pupenů tohoto majestátného stromu umí léčit paradentózu. Tinkturu nakapeme do malého množství teplé vody, chvíli podržíme v ústech a následně polkneme. Její společné užívání s <a href="https://serafinbyliny.cz/produkt/draci-krev_462">Dračí krví</a> je velmi účinné při boji s paradontózou.</p>
<h2>Zvýšená kazivost zubů</h2>
<p>Zdravé zuby souvisí nejenom se zubní hygienou, ale také s naší <strong>vnitřní „hygienou“</strong>. Chronické záněty sliznice žaludku a střev často způsobují <strong>přemnožení bakterií a plísní v trávicím traktu</strong>. Ty se pak dostávají k zubům a intenzivním působením na zubní sklovinu ji poškozují.</p>
<p>Nejčastější příčinou chronických zánětů v trávicím traktu je dlouhodobý stres, užívání léků, ale zejména potrava s přebytkem kyselinotvorných složek, která pak způsobuje trvale překyselený organismus.</p>
<p>Častým zdravotním problémem, který může poškozovat následně sklovinu zubů je také <a href="https://anetabenediktova.cz/reflux-jicnu-a-prirodni-lecba/">reflux jícnu</a>.</p>
<p>Jako prevenci je nutné upravit stravovací režim a užívat byliny na <a href="https://serafinbyliny.cz/produkt/odkyseleni-organismu_453">odkyselení organismu</a>.</p>
<p>Nyní již víte jak chránit své dásně a zuby, a by váš úsměv byl vždy okouzlující!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/09/zuby-2.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-09-08T09:36:32+00:00$q$,$q$https://anetabenediktova.cz/jak-na-bolestive-dasne-a-zuby-prirodni-cestou/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$aronie-moje-laska$q$,$q$Arónie, moje láska…$q$,$q$…a už je to tady. Každoroční boj mezi mnou a vykutálenými ptáčky. Jaký? No, přeci kdo dříve sklidí úžasné plody Černého jeřábu – arónie. Už jsme si spolu udělali za ty roky kompromis. Nechám jim část úrody a pak přes keříky hodím síťku, aby také něco zbylo na mne. Musím být však velmi obezřetná, jel$q$,$q$<blockquote>
<p>…a už je to tady. Každoroční boj mezi mnou a vykutálenými ptáčky. Jaký? No, přeci kdo dříve sklidí úžasné plody Černého jeřábu – arónie.</p>
</blockquote>
<p>Už jsme si spolu udělali za ty roky kompromis. Nechám jim část úrody a pak přes keříky hodím síťku, aby také něco zbylo na mne. Musím být však velmi obezřetná, jelikož drozdi, špačci i kosáci umí očesat stromek během pár hodin.</p>
<p>Název Temnoplodec černoplodý přesně vystihuje, jak vypadají její plody. Velké téměř černé kuličky se specifickou chutí. Mám je ráda jen tak za syrova. V ústech cítíte kombinaci zvláštní sladkosti, kyselosti a zároveň svíravosti.</p>
<p>Arónie ( Jeřáb černý, Temnoplodec černoplodý) je velmi účinná léčivá bylina, tedy spíše léčivý keř. <strong>V přírodním léčitelství je z něj využívají pupeny a plody</strong>. Nádherné červeně zbarvené listy na podzim pak potěší vaši duši.</p>
<p>Plody mají vysoký obsah červených barviv, které působí antioxidačně a <strong>chrání naše buňky</strong>. Obsahují jich cca 5krát víc než stejné množství modrých hroznů. Arónie obsahuje všechny důležité vitaminy a minerály, především velké množství <strong>rutinu, jódu a draslíku</strong>.</p>
<p>Extrakt <strong>z pupenů</strong> Černého jeřábu dokáže <strong>harmonizovat činnost štítné žlázy</strong> jak při snížené, tak i zvýšené funkci. <strong>Plody</strong> pak posilují <strong>imunitu, chrání náš kardiovaskulární systém, podporují pevnost a pružnost cévních stěn.</strong></p>
<p>Látky obsažené v plodech Arónie zlepšují <strong>zrak, čistí klouby od kyselých usazenin, lehce snižují krevní tlak, snižují překyselení žaludku, podporují koncentraci a vitalitu.</strong></p>
<p>Nejlepší léčebné použití plodů Černého jeřábu je přímá konzumace čerstvých, sušených nebo zmražených plodů. Mohou se také přidávat do bylinných čajů nebo třeba do ovesné kaše či jogurtu.</p>
<p>Jelikož máme všichni mlsné jazýčky, tak naše babičky vymyslely skvělé recepty na její zpracování. Jsou to různé džemy, marmelády, šťávy a také <strong>skvělý likér</strong>. Tak pojďme na něj…</p>
<p><img fetchpriority="high" src="https://anetabenediktova.cz/wp-content/uploads/2021/08/aronie-sber-225x300.jpg" alt="" /></p>
<p><strong><em>Potřebujeme:</em></strong></p>
<p>3 kg čerstvých plodů Černého jeřábu &#8211; Arónie</p>
<p>1 kg cukru nejlépe třtinového</p>
<p>1 litr rumu (používám kvalitní značky s příjemnou rumovou vůní)</p>
<p>1 citron v BIO kvalitě</p>
<p>hřebíček ( přiměřeně)</p>
<p>skořice celá (přiměřeně)</p>
<p>vanilkový lusk</p>
<p><strong><em>Jak na to…</em></strong></p>
<p>Čisté, umyté plody Arónie dáme do hrnce. Já je tam dávám i se stopkami. Zalijeme vodou tak, aby byly všechny plody těsně pod hladinou a dáme vařit.</p>
<p>Jakmile začne voda vařit přidáme několik plátků citronu, koření a vnitřní část vanilkového lusku.</p>
<p>Necháme povařit na mírném ohni 7-10 minut. Potom odstavíme a celou směs necháme v přikrytém hrnci na chladném místě ideálně do druhého dne.</p>
<p>Druhý den šťávu přecedíme přes bavlněný hadřík a z plodů se snažíme vymačkat také co nejvíce šťávy. Pozor! Arónie opravdu hodně barví!</p>
<p>Do přeceděné šťávy přidáme cukr a opět necháme za stálého míchání lehce převařit. Rozpuštěný cukr nám tekutinu mírně zahustí. Přilijeme rum a dávkujeme do lahví, které jsme si předem vypláchli horkou, převařenou vodou.</p>
<p>Likér je vynikající jen tak studený, ale za chladných zimních večerů si z něj můžete udělat aróniový grog na zahřátí anebo skvělý chutný čaj.</p>
<blockquote>
<p>Pokud si nestihnete vyrobit nějakou dobrou mňamku z Arónie, tak mohu doporučit tento sirup: <a href="https://www.serafinbyliny.cz/produkty-sirup-z-aronie-extra-detail-14840">zde</a></p>
<p>Tinkturu z pupenů Arónie na harmonizaci vaší štítné žlázy pak naleznete <a href="https://www.serafinbyliny.cz/produkty-cerny-jerab-tinktura-z-pupenu-detail-269">zde</a></p>
</blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/08/cerny-jerab-plod.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2022-08-31T10:51:23+00:00$q$,$q$https://anetabenediktova.cz/aronie-moje-laska/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$strach$q$,$q$Strach$q$,$q$Jednoduché slovo strach. Zkusme se zamyslet nad tím, kolikrát za den v běžném hovoru slovo strach použijeme. Mám strach, že mi ujede vlak… Mám strach, že se nastydnu… Mám strach, že nestihnu uvařit… Mám strach, že to nezvládnu… Slovních spojení a vět by zde mohlo být napsáno desítky. Slovo strach po$q$,$q$<p>Jednoduché slovo strach. Zkusme se zamyslet nad tím, kolikrát za den v běžném hovoru slovo strach použijeme.</p>
<blockquote><p>Mám strach, že mi ujede vlak…</p>
<p>Mám strach, že se nastydnu…</p>
<p>Mám strach, že nestihnu uvařit…</p>
<p>Mám strach, že to nezvládnu…</p></blockquote>
<p>Slovních spojení a vět by zde mohlo být napsáno desítky. <strong>Slovo strach používáme téměř bezmyšlenkovitě</strong> v průběhu našeho hovoru, ale i v průběhu našeho vnitřního přemýšlení.</p>
<blockquote>
<p>Každé slovo, které používáme, které vyřkneme má nějakou energii. Na tuto energii okamžitě reaguje naše tělo. <strong>Slovo strach má velmi negativní energii</strong>, dalo by se říci destrukční a sebedestrukční energii.</p>
</blockquote>
<p>Slovem strach podvědomě ve svém organismu sdělujeme, že jsme v ohrožení. Naše tělo a náš mozek se řídí při své funkci a při svých reakcích našimi emocemi. <strong>Slovem strach spouštíme reakci „boj nebo útěk“</strong> se všemi jejími následky.</p>
<p><strong>Při této reakci</strong> organismus během několika málo sekund vyprodukuje chemické látky, které ochromí naše trávení a náš imunitní systém a zároveň extrémně nabudí srdce, svaly a zatíží nadledvinky, štítnou žlázu a hypofýzu. <strong>Naše tělo je vykolejeno ze své rovnováhy.</strong></p>
<p>Kolikrát za den řekneme slovo strach, kolikrát za den se vychýlíme z rovnováhy zdraví a klidu? Potom se zákonitě dostavuje únava, vyčerpání a nemoc.</p>
<h2>Proč slovo strach používáme tak často?</h2>
<p><strong>Malé děti se přirozeně nebojí</strong>. Pozorujte někdy ročního „špunta“ jak poznává svět. Strach u něj neuvidíte. Všechno vezme do svých malých prstíků, vše ochutná, nebojácně se vrhá na každou dobrodružnou cestu.</p>
<p>Strach se nám začíná dostávat do podvědomí díky lidem, kteří nás v útlém věku ovlivňují. Tito lidé nás učí poznávat život a svět, <strong>učí nás, z čeho máme mít strach</strong>. Ano, některá upozornění na nebezpečí jsou důležitá. Větší část strachů však své opodstatnění nemá, předáváme si tato „zaklínadla&#8220; z pokolení na pokolení.</p>
<blockquote><p>Nechoď ven, prší, budeš nemocný…</p>
<p>To nezvládneš….</p>
<p>Nejsi dost dobrý, aby si mohl…</p>
<p>V noci jsou bubáci….</p>
<p>Utíkej, ať to stihneme….</p></blockquote>
<h2>Co to znamená?</h2>
<p>Slovo strach a vše s ním spojené nám blokuje žít klidný naplněný život. <strong>Blokuje nám vidět krásy života a radovat se z něj</strong>. Nedovolí nám plnit si své sny a být jako to malé radostné dítě poznávající svět. Slovo strach z nás <strong>dělá ustrašené, nemocné lidi, kteří jsou dobře ovladatelní.</strong></p>
<h2>Co s tím?</h2>
<p><strong>Pozorujte svoji řeč</strong> a svoji <strong>mysl</strong>. Zkuste cíleně ze svého slovníku <strong>vynechávat slovo strach</strong>. Domluvte se s rodinou či přáteli a hrajte hru, ve které slovo strach je zakázáno.</p>
<p>Pokud vám přijde <strong>myšlenka strachu</strong>, tak se na ní <strong>podívejte</strong>. Velmi dobré je si jí napsat. Napsat si, <strong>čeho se vlastně bojíte</strong>. Co nejvíc si ten strach konkretizovat. Prohlédněte si jej a zamyslete se do hloubky nad tím, jestli je opravdu <strong>opodstatněný</strong>.</p>
<p><strong>Zjistíte, že většina strachů nemá reálný základ</strong>. Jsou to jen naše automatické vzorce chování. Ale vy máte moc a sílu je změnit! Tak do toho! Stačí si na ně jen posvítit, prohlédnout si je a tak jako když ve tmě rozsvítíte, tak najednou zmizí.</p>
<h2>Cesta k uzdravení</h2>
<p>Poslední roky se o zdraví zajímáme více a více. Mnoho lidí objevuje<strong> sílu bylin a přírodní léčby</strong>. To je však jen jedna část, která nám pomáhá k uzdravení. <strong>Druhá, neméně podstatná je naše podvědomí, naše mysl</strong>. Podvědomé reakce a emoce z nich vycházející nám určují nejenom stav zdraví či nemoci, ale i to jestli jsme schopni se opravdu vyléčit.</p>
<p>Pracujte tedy se svým podvědomím a primárně se svými strachy. Základní návod jsem vám napsala.</p>
<blockquote>
<p>Prohlédněte si své strachy, pochopte je a s láskou je propusťte&#8230;</p>
<p>..a když je krize, tak se prostě začněte smát!</p>
</blockquote>
<p>Další techniky můžete vyzkoušet na mých seminářích. Více <a href="https://anetabenediktova.cz/sluzby/kurzy-a-seminare/">zde</a>.</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/08/smejici-se-kun.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-08-22T09:39:18+00:00$q$,$q$https://anetabenediktova.cz/strach/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$molusky-a-prirodni-lecba$q$,$q$Molusky a přírodní léčba$q$,$q$Název Molusky za sebou skrývá zdravotní problém v podobě nehezkých výrůstků na kůži, které mají obvykle bílou nebo růžovou barvu. Mívají velikost špendlíkové hlavičky, jsou ostře ohraničené a mohou svědit, bolet, rudnout a bobtnat. Vyskytují se kdekoli na těle, včetně tváře, krku a genitálií. Molusk$q$,$q$<p>Název Molusky za sebou skrývá zdravotní problém v podobě nehezkých <b>výrůstků na kůži</b>, které mají obvykle bílou nebo růžovou barvu. Mívají velikost špendlíkové hlavičky, jsou ostře ohraničené a mohou <b>svědit, bolet, rudnout a bobtnat</b>. Vyskytují se kdekoli na těle, včetně tváře, krku a genitálií. Moluskami často trpí malé děti, ale i dospělí.</p>
<h2>Kde je příčina?</h2>
<p>Za tuto infekční chorobu může lehce <b>přenosný virus</b> Molluscum contagiosum. Nákazu s inkubační dobou od 2 do 7 týdnů <b>může vyvolat fyzický kontakt</b> s infikovanou osobou i sdílení ručníků, povlečení, oděvů u velmi malých dětí pak i hraček.</p>
<p><b>Virus se velmi rychle šíří ve vodě</b>. Často může za Molusky bazén, a to hlavně ten veřejný. Kromě bazénů je velké riziko přenosu ve <b>společných sprchách, v saunách, lázních a vířivkách</b>. Molusky sice nepatří mezi závažná onemocnění, zato jsou velmi nepříjemné. Léčba u dětí i dospělých může být poměrně dlouhá a otravná.</p>
<h2>Kdo je nejvíc ohrožen?</h2>
<p>Molusky se objevují nejčastěji v <b>dětských kolektivech</b> a postihují především děti do 7 let věku. Ve větší míře napadají děti s <strong>oslabenou imunitou</strong>.</p>
<p>Nevyhýbají se však ani dospělým osobám. Velmi často dochází k přenosu infekce škrábáním postižených částí těla či holením. Mnoho dospělých si Molusky předává také <b>pohlavním stykem</b>.</p>
<p>Ačkoliv Molusky může mít úplně každý, někteří lidé jsou virem ohroženi více než jiní. Nejčastěji se nakazí <b>lidé s oslabenou imunitou.</b> Dalšími rizikovými skupinami jsou &#8222;<b>ekzematici&#8220;, alergici a také lidé vystavení dlouhodobému psychickému vypětí. </b>Průběh nemoci u nich pak může být výraznější a léčba o poznání delší.</p>
<h2>Co s nimi?</h2>
<p>Molusky a jejich léčba je většinou řešena u dětí při masivním výskytu výrůstků a u dospělých při výskytu molusek v oblasti pohlavních orgánů a análního otvoru.</p>
<h3><b>Klasická medicína řeší léčbu molusek:</b></h3>
<p><b>Kryoterapií</b> &#8211; zmrazením výstupků tekutým dusíkem</p>
<p><b>Vypíchnutím</b> &#8211; narušení středu výstupku a jejich následné seškrábnutí</p>
<p><b>Laserovou terapií</b></p>
<p>Všechny zmíněné možnosti vyžadují<b> trénovaného medicínského specialistu</b>. Ten během výkonu může, ale nemusí pacientovi podat lokání anestezii. Krátce po zákroku může nemocný pociťovat bolest.</p>
<p><b>Celkově zejména u dětí jsou tyto metody bolestivé a velmi stresující.</b> Neodborným zásahem může dojít k zanesení infekce do rány nebo dalšímu šíření nemoci.</p>
<h3><b>Přírodní medicína nabízí velmi účinné možnosti léčby:</b></h3>
<p>Ta se vždy skládá ze <b>zevní aplikace <a href="https://serafinbyliny.cz/produkt/bradavicove-mazani_476" target="_blank" rel="noopener">bylinných extraktů</a></b>, ale je nutné zároveň užívat i <b>přírodní přípravky vnitřně</b>, a to takové, které mají přirozené <b>antivirotické</b> působení. Nejčastěji to je <a href="https://serafinbyliny.cz/produkt/draci-krev_462">Dračí krev</a> nebo některé <a href="https://serafinbyliny.cz/produkt/imunofungin-bio_456">léčivé houby</a></p>
<p>Pokud opomeneme vnitřní užívání některého z přípravků, tak bývá léčba zdlouhavá a ne vždy úspěšná.</p>
<p>Důležitá je <b>trpělivost a každodenní péče</b>. Na postižené místo je nutné každý den, ideální na noc, aplikovat bylinný extrakt a nechat jej zaschnout. Jelikož se jedná o přírodní produkt, tak ten nedráždí kůži a nezpůsobuje nepříjemné pálení a poškozování pokožky.</p>
<h2>Prevence je důležitá</h2>
<p>Nejúčinnějším opatřením je dodržování <b>základních hygienických zásad</b>. <b>Není vhodné sdílet osušky, šaty či mycí houby.</b> Pokud to je možné, vyvarujte se půjčování vybavení, jakým jsou helmy, rukavice či jiné věci, které přijdou do přímého kontaktu s pokožkou.</p>
<p>Opatrný by člověk měl být<b> i v případě, kdy se u něj molusky projeví</b>. Konkrétně by měl totiž dělat vše pro to, aby neinfikoval lidi v jeho okolí. Rozhodně by tedy s nikým neměl sdílet nemyté předměty a pokud se u něj výrůstky nacházejí v oblasti genitálií, je na místě i sexuální zdrženlivost.</p>
<blockquote>
<p><strong>Můj tip při Moluskách</strong></p>
<p>děti do 5-ti let zevně <a href="https://serafinbyliny.cz/produkt/bradavicove-mazani_476">Bradavicové mazání,</a> vnitřně <a href="https://serafinbyliny.cz/produkt/serafinkuv-detsky-sirup_234">Serafínkův dětský sirup</a></p>
<p>děti od 5-ti let zevně <a href="https://serafinbyliny.cz/produkt/bradavicove-mazani_476">Bradavicové mazání</a>, vnitřně <a href="https://serafinbyliny.cz/produkt/imunofungin-bio_456">IMUNOfungin BIO</a></p>
<p>dospělí zevně <a href="https://serafinbyliny.cz/produkt/bradavicove-mazani_476">Bradavicové mazání</a>, vnitřně <a href="https://serafinbyliny.cz/produkt/draci-krev_462">Dračí krev</a></p>
</blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/08/molusky.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-08-14T17:53:05+00:00$q$,$q$https://anetabenediktova.cz/molusky-a-prirodni-lecba/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$jak-posilit-telo-v-srpnu$q$,$q$Jak posílit tělo v srpnu$q$,$q$Tak jako každý měsíc, tak i srpen podle pravidel čínské medicíny patří jednomu z hlavních tělesných orgánů. Ten bychom měli v tomto čase posilovat a chránit. Jaký to tedy je? „ Tři ohřívače“! Tento zvláštní pojem vychází z principů čínské medicíny a jejího chápání fungování těla a orgánů. Energie v $q$,$q$<p>Tak jako každý měsíc, tak i srpen podle pravidel čínské medicíny patří jednomu z hlavních tělesných orgánů. Ten bychom měli v tomto čase posilovat a chránit.</p>
<p>Jaký to tedy je? <b> „ Tři ohřívače“! </b></p>
<p>Tento zvláštní pojem vychází <b>z principů čínské medicíny</b> a jejího chápání fungování těla a orgánů.</p>
<h2>Energie v meridiánech</h2>
<p>„Trojitý ohřívač“ – pro většinu z nás se jedná o cizí pojem a neumíme si pod ním nic představit. Kdo se však trošku zajímá o přírodní medicínu a její principy tak ví, že všechny východní národy pracují <b>s nějakou formou energie</b>, která proudí v organismu a <b>vyživuje jednotlivé orgány</b>.</p>
<p>Ayurvéda s energií – prána, čínská medicína pracuje s energií, kterou <b>nazývá čchi</b>. Energie čchi <b>proudí v tzv. meridiánech</b>, což jsou neviditelné dráhy, které prochází po přesně daných místech na těle.</p>
<p>Každá z těchto <b>drah patří k jednomu orgánu,</b> který <b>energeticky vyživuje</b>, ale také energeticky vyživuje všechna místa v průběhu svého průchodu. Jakákoliv <b>překážka v proudění</b> energie v dráze pak <b>způsobí onemocnění</b> vyživovaného orgánu.</p>
<h2>Jak funguje akupunkturní bod?</h2>
<p>Každá z těchto drah má na přesně daném místě průběhu své dráhy různé <b>množství akupunkturních bodů</b>.</p>
<p>Akupunkturní bod si můžeme představit jako malý<b> vodovodní kohoutek</b>. Jeden bod na dráze funguje na <b>připuštění (přidání) energie</b>, jiný zase <b>na upuštění.</b> Také tam jsou body, kterými mohu předat <b>energii z jedné dráhy do druhé</b>.</p>
<p>Jedná je o velmi složitý, ale účinný systém, kterého využívá akupunktura k léčení nemocí. Tyto dráhy můžeme <b>ovlivňovat</b> nejenom aplikací <b>akupunkturních jehel</b>, ale třeba i správnou<b> akupunkturní masáží</b>, anebo i <b>zahříváním akupunkturních bodů</b>. Každý člověk sám jednotlivě si může upravit tok energie v těchto drahách různými formami cvičení. Nejznámější a nejúčinnější cvičení se nazývá čchi-kung.</p>
<h2>Základní životní energie je v ledvinách</h2>
<p><b>„Tři ohřívače“</b> je vlastně <b>neviditelný orgán</b>, který uvnitř nás <b>rozvádí naší základní životní energii</b>, energii čchi do orgánů, tak aby mohly dobře pracovat, abychom mohli žít. Je to vlastně takový velký základní meridián, na který jsou pak napojeny ostatní meridiány – akupunkturní dráhy. <b>Základní životní energie čchi</b>, která nám byla daná při narození<b> se nachází v ledvinách</b>. Ledviny jsou z pohledu života – životní energie nejdůležitější orgán.</p>
<blockquote>
<h3>První doporučení : V srpnu je důležité dodržovat pitný režim a chránit své ledviny.</h3>
</blockquote>
<p><b>Neprochladněte</b> ve studené vodě nebo třeba zpocení při sportu nebo práci na zahrádce. Dopřejte svým ledvinám <b>vlažné nápoje</b>, nejlépe bez cukru. Můžete zařadit <b>bylinné čaje</b> na <a href="https://serafinbyliny.cz/produkt/ledviny-zeny-porcovany-caj_424">ledviny</a>, ale i třeba náš <b><a href="https://serafinbyliny.cz/produkt/letni-caj_452">Letní čaj</a> </b>pro běžné pití. Letní čaj obsahuje mimo jiné rooibos plný minerálů. Ty v létě přirozeně ztrácíme pocením, a tak je přirozeně můžeme doplnit. Nápoje plné cukru a ledu určitě vašim ledvinám dobře nedělají.</p>
<p>Zkuste si <b>hýčkat své osobní vztahy</b>, jelikož vztahové problémy s našimi nejbližšími nám nejvíce vyčerpávají naší životní čchi z ledvin.</p>
<blockquote>
<h3>Druhé doporučení: V srpnu čerpejte energii z přírody a probuďte své hormony štěstí</h3>
</blockquote>
<p>„Trojitý ohřívač“ úzce souvisí s funkcí našich <b>žláz s vnitřní sekrecí</b>. Hlavním <b>„panem řídícím“</b> endokrinního systému je <b>hypofýza a hypotalamus</b>. Tyto žlázy s vnitřní sekrecí nejenom, že řídí ostatní žlázy, ale také <b>ovlivňují naší náladu</b> – produkují tzv. hormony štěstí.</p>
<p>Jestliže jich máte málo, tak právě<b> pobyt v přírodě </b>se zapojením <b>pohybové aktivity</b> vám může účinně pomoci. Pokud ani to nestačí, tak zkuste přidat <strong>byliny či minerály</strong> , které pomáhají překonávat stres a dodávají ztracenou energii. Hlavní bylinou v tomto případě je <a href="https://serafinbyliny.cz/herbar/bylinkar_2/puerarie-lalocnata-kudzu_193">kudzu</a> obsažené v kapslích <a href="https://serafinbyliny.cz/produkt/pohoda_126">Pohoda</a> nebo <a href="https://serafinbyliny.cz/produkt/rozchodnice-tinktura-z-pupenu_187">Rozchodnice</a>. Z minerálů pak vede <a href="https://serafinbyliny.cz/produkt/horcik-b6_118">Hořčík</a> s vitamíny B</p>
<blockquote>
<h3>Třetí doporučení:  V srpnu podpořte svojí štítnou žlázu</h3>
</blockquote>
<p>V souvislosti s „třemi ohřívači“ se jeví velmi <b>důležitá také <a href="https://anetabenediktova.cz/stitna-zlaza-nas-stit-pred-zevnim-svetem/">štítná žláza</a></b>, která je přímo jak energeticky, tak i hormonálně napojená na hypofýzu.</p>
<p>Štítná žláza velmi <b>citlivě reaguje</b> na úbytek energie zejména v souvislosti <b>se stresem</b>, ale také patří mezi orgány <b>termoregulace</b>. Více o nemocech a přírodní léčbě štítné žlázy najdete <a href="https://anetabenediktova.cz/stitna-zlaza-nas-stit-pred-zevnim-svetem/">zde</a>.</p>
<p>V měsíci srpnu právě její zatížení bývá velké. Pokud trpíte poruchou funkce štítné žlázy, tak nyní je právě období, kdy je nutné jí <b>pomoci správně zvolenými bylinami</b>.</p>
<p>Štítné žláze můžeme pomoci i pravidelnou masáží krku směrem od brady dolů ke klíčním kostem.</p>
<p><b>Víte, že štítnou žlázu posílíte pravidelným zpěvem? </b>Vibrace v oblasti krku harmonizují její funkce.</p>
<p>V srpnu zpívejte, cvičte, pijte vlažné čaje a bude vám dobře!</p>
<p>TIP: nevíte jak zvýšit svoji životní energii? Přijďte na některý z mých seminářů! Ukáži vám jak na to.</p>
<p>Více <a href="https://anetabenediktova.cz/sluzby/kurzy-a-seminare/">zde</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/07/DSC01195.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-07-27T18:16:03+00:00$q$,$q$https://anetabenediktova.cz/jak-posilit-telo-v-srpnu/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$bolave-zily-a-komonice$q$,$q$Bolavé žíly a komonice$q$,$q$Bolavé, oteklé nohy, pocit těžkých nebo naopak neklidných nohou. To bývá častý problém zejména ženské části populace. S teplým počasím se pak tyto problémy značně zhoršují. Příčinou jsou většinou křečové žíly a s tím spojená nedostatečná funkce celého cévního a lymfatického systému. Křečové žíly moh$q$,$q$<blockquote>
<p>Bolavé, oteklé nohy, pocit těžkých nebo naopak neklidných nohou. To bývá častý problém zejména ženské části populace. S teplým počasím se pak tyto problémy značně zhoršují.</p>
</blockquote>
<p>Příčinou jsou většinou <strong>křečové žíly</strong> a s tím spojená nedostatečná funkce celého cévního a <strong>lymfatického systému.</strong></p>
<p>Křečové žíly mohou být dlouhou dobu jen kosmetickým problémem, často s nenápadnými projevy, jako je zvýšený <strong>pocit napětí v dolních končetinách nebo občasné otoky</strong>. Pokud o své tělo a své cévy nepečujeme, mohou přejít do daleko závažnějších obtíží.</p>
<p><strong>Komplikací</strong> neléčených křečových žil bývají <strong>otoky, změny barvy kůže, zánět žil, bércový vřed</strong> anebo i trombóza</p>
<h2>Jak křečové žíly vznikají</h2>
<p>Křečové žíly vznikají vlivem celé řady faktorů odvíjejících se od životního stylu. <strong>Dlouhé stání nebo naopak sezení, nadváha, nadměrné sportovní zatížení, hormonální antikoncepce či jiné hormonální léky.</strong></p>
<p>Jedním z důležitých faktorů působících na vznik křečových žil je celkové vnitřní prostředí těla ovlivněné stravou. Pokud tělo stále překonává<strong> chronické překyselení</strong>, tak vznik křečových žil je jedním z důsledků.</p>
<h2>Role pokožky</h2>
<p>Jestliže chceme předejít tomuto nepříjemnému onemocnění, které se nás limituje esteticky i v řadě aktivit, pak je nutné dodržovat nejen některé zdravotní praktiky, ale důsledně pečovat o zdraví pokožky na postižených místech a o žilní stěny pod pokožkou. <strong>Chřadnoucí pokožka neposkytuje rozšiřujícím se žilám dostatečnou podporu a tak se onemocnění urychluje.</strong></p>
<p>Pro zachování kvality pokožky a zmírnění progrese onemocnění, je třeba denně aplikovat přírodní přípravky s obsahem látek, které pokožku vyživují a regenerují, a látek pro posílení pružnosti žilní stěny.</p>
<p>Velmi účinná je mast <a href="https://serafinbyliny.cz/produkt/ruticelit_634">Ruticelit</a> s obsahem celé řady léčivých bylin a éterických olejů. Pružnost a kvalitu kůže můžeme zlepšit také užíváním <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109">přírodních vitamínů</a> a minerálů. Důležitý je zejména betakaroten, vitamín E a zinek.</p>
<h2>Byliny na žíly a lymfu</h2>
<p>Křečové žíly, zánět žil, žilní otoky či bércové vředy je <strong>potřeba léčit i vnitřně</strong>. Tedy užívat byliny, vitamíny a minerály, které působí na zpevnění cévní stěny a proti jejímu zánětu. Mezi takové byliny patří <a href="https://serafinbyliny.cz/produkt/kastan-tinktura-z-pupenu_172">kaštan</a>, pohanka, <a href="https://serafinbyliny.cz/produkt/zily-a-lymfa-smes-z-pupenu_209">kůra z vrby</a> a také komonice.</p>
<h2>Komonice lékařská</h2>
<p>Komonice, neboli <strong>kadeř svatého Jana</strong> má i celou řadu dalších lidových názvů jako koňský jetel, medový jetel, včelí bylina, kameníček. Měla by se sbírat na svatého Jána, kdy její léčivá síla je největší.</p>
<p>Nejvíce účinných látek obsahuje celá horní část žlutě kvetoucí lodyhy. Jednou z nejzajímavějších látek přítomných v komonici je <strong>kumarin</strong>, který významně snižuje<strong> srážlivost krve.</strong> Právě výzkum komonice vedl k vynálezu léku <em>warfarin</em>, který se dnes používá jako silný lék na ředění krve zejména u lidí po trombózách, srdečních onemocněních či u zánětů žil.</p>
<p>Sušená nať komonice lékařské se v přírodní léčbě používá zejména při léčbě <strong>křečových žil, zánětů žil, lymfatických a žilních otoků, hemoroidů </strong>nebo u osob trpících <strong>poruchami krevní srážlivosti.</strong></p>
<p>Jako další účinky je uváděné působení na kašel, astma, proti střevním a žaludečním křečím, při bolestech hlavy či revmatismu.</p>
<p>Bylina sama není chuťově moc dobrá, proto je vhodné jí míchat společně s dalšími bylinami do <strong>léčivých čajů.</strong></p>
<p><strong>Základní kontraindikací</strong> při jejím užívání je současné užívání léku <em>Warfarin či Heparin</em>. V tomto případě může dojít k velkému naředění krve a případnému vnitřnímu krvácení.</p>
<p>Komonici by také neměly užívat <strong>malé děti a těhotné ženy.</strong></p>
<p>Zajímavostí je, že komonice zavěšená ve dveřích či okně dokáže svojí vůní odpuzovat hmyz a vložená do skříně či matrací odpuzuje moly.</p>

<h3><strong>Moje tipy</strong></h3>
<p><strong>Křečové žíly:</strong> pijte čaj <a href="https://serafinbyliny.cz/produkt/zily-porcovany-caj_449">Žíly</a> a k tomu užívejte tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/kastan-tinktura-z-pupenu_172">Kaštan</a> a kapsle <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109">Multiserafin</a>. Zevně pak mast <a href="https://serafinbyliny.cz/produkt/ruticelit_634">Ruticelit</a></p>
<p><strong>Křečové žíly a otoky:</strong> střídejte po dni čaje  <a href="https://serafinbyliny.cz/produkt/zily-sypany-caj_232">Žíly</a> a <a href="https://serafinbyliny.cz/produkt/lymfa-sypany-caj_175">Lymfa</a> k tomu užívejte tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/kastan-tinktura-z-pupenu_172">Kaštan</a> a kapsle <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109">Multiserafin</a>. Zevně pak mast <a href="https://serafinbyliny.cz/produkt/ruticelit_634">Ruticelit</a></p>
<p><strong>Nechcete či nemůžete pít čaje:</strong> užívejte směs z pupenů <a href="https://serafinbyliny.cz/produkt/zily-a-lymfa-smes-z-pupenu_209">Žíly a lymfa</a> a kapsle <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109">Multiserafin</a>. Zevně pak mast <a href="https://serafinbyliny.cz/produkt/ruticelit_634">Ruticelit</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/06/zily.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-06-29T06:54:15+00:00$q$,$q$https://anetabenediktova.cz/bolave-zily-a-komonice/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$lymfaticky-system-v-letnich-mesicich$q$,$q$Lymfatický systém v letních měsících$q$,$q$Problémy s otoky, špatným prokrvením, celulitidou či pocitem vnitřního tlaku zejména v končetinách trápí celou řadu osob. V létě bychom těmto obtížím a potažmo celému lymfatickému systému měli věnovat speciální péči. Lymfatický systém je v našem těle propojený se systémem cévním. Na rozdíl od něj ne$q$,$q$<blockquote>
<p>Problémy s otoky, špatným prokrvením, celulitidou či pocitem vnitřního tlaku zejména v končetinách trápí celou řadu osob. V létě bychom těmto obtížím a potažmo celému lymfatickému systému měli věnovat speciální péči.</p>
</blockquote>
<p>Lymfatický systém je v našem těle propojený se systémem cévním. Na rozdíl od něj nemá pumpu ve formě srdce. Lymfa je v lymfatických cestách poháněna zejména smršťováním svalů, tedy pohybem. <strong>Lymfatický systém reaguje nejenom na pohyb, ale i na stravu, nápoje, léky i psychiku.</strong> Pojďme to tedy prozkoumat blíže.</p>
<h2>Strava a lymfatický systém</h2>
<p>Strava v létě je vhodná <strong>syrovější a lehčí</strong>. Jezte potraviny pomáhající odvodnit jako jsou <strong>melouny, grepy, citrusy</strong>. Léto je jediné období, kdy vám lymfa odpustí ovoce, které ochlazuje, což jsou všechny citrusy. Zařazujeme 1-2 dny v týdnu kdy pijeme pouze zeleninové šťávy. Jezte hodně teplé kaše z amarantu, slzovky, pohanky, jáhel, jedno zdali k snídani, obědu či večeři. Neomezeně, klidně každý den.</p>
<p><strong>Co bychom měli vyloučit?</strong> Zejména <strong>mléčné</strong> výrobky a přidaný <strong>cukr</strong>.  Zmrzliny nahraďte ovocnými bez přidaného cukru. <strong>Nepijte kávu!</strong> Omezte <strong>banány, lepek, pečivo a brambory</strong>. V létě chce tělo též odpočívat a netrávit <strong>těžká masa, těstoviny a omáčky</strong>. Chce lehkost a odpočinek tak jako my.</p>
<p><img fetchpriority="high" src="https://anetabenediktova.cz/wp-content/uploads/2021/06/letni-caj-apatyka.png" alt="" /></p>
<h2>Nápoje a lymfatický systém</h2>
<p>V letním období máme tendenci tělo ochlazovat a dopřávat mu od přehnané klimatizace v obchodech a kancelářích po chlazené nápoje plné ledu. Ani jeden extrém není přirozený našemu vnitřnímu prostředí. Ženy, které trpí na otoky a zavodnění mají často chladné tkáně, studené končetiny a tím vnitřní chlad. Často si stěžují na studené nedokrvené končetiny. <strong>Proto se jejich tělo potřebuje vnitřně, a to i v létě ohřívat</strong>. Tak jako to dělají východní kultury, kteří i parných dnech stále popíjejí horký zelený či černý čaj a nikdy je neuvidíte pít ledový nápoj s ledem. Dlouhá tisíciletí ví, že je nevhodný. Proto i v létě více <strong>pijte převážně teplou či vlažnou vodu nebo bylinné čaje</strong>. Vhodný je také čaj zelený, černý nebo rooibos.</p>
<h2>Pohyb a lymfatický systém</h2>
<p>Lymfu si zatěžujeme a zakyselujeme nadměrnou fyzickou zátěží, nadměrným sportováním. Pravdou ale je, že zde platí zlaté pravidlo „všeho s mírou“ Nadměrnou zátěží svalů se totiž vylévá do tkání kyselina mléčná a močová. Tkáně a lymfa se okyselují, tuhnou a ochlazují, proto je dobré organismus stále vnitřně ohřívat, a to jak teplými tekutinami, tak stravou. Kyselé prostředí je živnou půdou pro tvorbu a usazování toxinů, veškerého odpadu a chemie. To na sebe nabaluje tuky, vodu, hleny, odpady, toxiny, chemie a plísně ze stravy. Výsledkem je nejen celulitida, ale též otoky, obezita a odulost.</p>
<p><strong>Jakýkoliv aerobní pohyb, fitness, posilování, běhání, rotoped, kolo, dlouhé túry či procházky nejsou v teplém létě vhodné.</strong> Platí zde pravidlo “dělat to, co mému tělu dělá dobře a po čem se cítí dobře”.</p>
<p>Vždy buďte sami k sobě upřímní a odpovězte si, zdali po sportu, který děláte se cítíte nejen psychicky ale i fyzicky dobře.  Jste po procházce, cvičení krásně splasklé, štíhlejší, lehčí? Pokud ano, tak pak je to v pořádku.</p>
<p>Pro lymfatický systém v létě je <strong>vhodné protahování, jóga, lehká chůze a zejména plavání.</strong>  Slané moře je nejlepší odkyselující koupel a masáž mořskými vlnami udělá dobře každému. I sladké vody naší zeměpisné šířky nám poskytnou skvělou koupel, a to zejména vody přírodní, které obsahují přirozenou rašelinu a slatinu. Někde jí je více, jinde méně, ale i tak nás <strong>přirozeně odkyselí a při plavání rozproudí lymfatický systém.</strong></p>
<h2>Byliny a houby</h2>
<p>Na lymfatický systém najdeme celou řadu byliny a také hub. Všechny jej umí rozproudit a odstranit otoky.</p>
<p><a href="https://serafinbyliny.cz/produkt/svizel-tinktura-z-bylin_388"><strong>Svízel syřišťový</strong></a> – úžasná bylina, která dokáže s naším lymfatickým systémem „dělat divy“. Umí skvěle odvodnit a „prošťouchnout“ ucpaný lymfatický systém. Celkově detoxikuje, podporuje funkce ledvin a také je čistí.</p>
<p><a href="https://serafinbyliny.cz/produkt/tuzebnik-tinktura-z-pupenu_191"><strong>Tužebník jilmový</strong></a> – nádherná bylina s bílým květenstvím podobným šeříku umí odstranit soli z těla a z lymfatického systému, a tím působí skvěle mimo jiné proti obtěžující celulitidě</p>
<p><a href="https://serafinbyliny.cz/produkt/kopriva-tinktura-z-pupenu_174"><strong>Kopřiva dvoudomá</strong></a> – chronicky známá bylina tisíce účinků. Jedním z nich je schopnost snižovat otoky a čistit krev a lymfatický systém</p>
<p><a href="https://anetabenediktova.cz/polyporus-houba-pro-vasi-lymfu-a-imunitu/"><strong>Polyporus</strong> </a>– vzácná jedlá houba, která se používá v tradiční přírodní medicíně ve formě extraktu. Ten dokáže velmi účinně snižovat ledvinové a lymfatické otoky, a mimo jiné silně podporuje imunitní systém a působí proti zánětům.</p>

<blockquote>
<h3>Můj tip:</h3>
<p><strong>Na lymfatické otoky a celulitidu:</strong> pijte střídavě po dni čaje <a href="https://www.serafinbyliny.cz/produkty-lymfa-bylinny-caj-porcovany-detail-1594">Lymfa</a> a <a href="https://www.serafinbyliny.cz/produkty-pomerancova-kuze-bylinny-caj-porcovany-detail-1578">Pomerančová kůže</a>. K tomu denně užívejte kapsle <a href="https://www.serafinbyliny.cz/produkty-polyporus-s-jitrocelem-40-polysacharidu-detail-17269">Polyporus</a> s Jitrocelem</p>
<p><strong>Na běžné letní pití a prevenci proti lymfatickým otokům:</strong> Pijte <a href="https://www.serafinbyliny.cz/produkty-letni-caj-bylinny-caj-sypany-detail-2355">Letní čaj</a> s obsahem rooibosu a k tomu užívejte tinkturu<a href="https://www.serafinbyliny.cz/produkty-svizel-tinktura-z-bylin-detail-252"> Svízel</a>.</p>
<p><strong>Nechcete pít bylinné čaje? Nevadí!</strong> Užívejte tinkturu <a href="https://serafinbyliny.cz/produkt/zily-a-lymfa-smes-z-pupenu_209">Žíly a lymfa</a> a k tomu pijte dostatečné množství vody.</p>
<p>Mastička<a href="https://serafinbyliny.cz/produkt/ruticelit_634"> Ruticelit</a> vám uleví ve velmi krátké chvíli od <strong>bolesti, otoku a pocitu těžkých nohou</strong></p>
</blockquote>

<p>Přeji všem krásné léto plné koupání, slunečních paprsků a celkové pohody!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/06/zena-u-more.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-06-17T08:00:04+00:00$q$,$q$https://anetabenediktova.cz/lymfaticky-system-v-letnich-mesicich/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$leciva-sila-cerneho-bezu$q$,$q$Léčivá síla černého bezu$q$,$q$Bez černý – statný keř, který nám v každém ročním období nabízí nějakou svoji část jako výborný léčivý prostředek. Brzy na jaře pupeny a mladé větvičky, na podzim plody a více jak půl roku listy, které ve formě obkladu zbavují naše tělo zhmožděnin a revmatických bolestí. Na začátku léta se můžeme tě$q$,$q$<p><strong>Bez černý</strong> – statný keř, který nám v každém ročním období nabízí nějakou svoji část jako výborný léčivý prostředek. Brzy na jaře <strong>pupeny a mladé větvičky</strong>, na podzim <strong>plody </strong>a více jak půl roku <strong>listy</strong>, které ve formě obkladu zbavují naše tělo zhmožděnin a revmatických bolestí. <strong>Na začátku léta se můžeme těšit z nádherně vonících žlutobílých květů.</strong></p>
<p>Léčivou sílu květů černého bezu si můžeme nejenom ihned užít, ale hlavně <strong>uchovat na zimu</strong>, kdy ji budeme potřebovat daleko více. Připravit si můžeme kloktadlo, mast, ale i lahodnou limonádu či sirup. Usušené květy pak užívat celý rok.</p>
<h3>Čaj z květů černého bezu</h3>
<p>Bylinný čaj z květů je <strong>močopudný, dokáže snížit horečku, vyvolat pocení</strong>, nebo dokonce <strong>zmírnit dráždivý kašel.</strong> Působí také <strong>proti bolesti svalů a kloubů</strong>. Sušený květ černého bezu můžeme kombinovat třeba s květem lípy nebo se šalvějí.</p>
<p><strong>Jak sušit černý bez</strong></p>
<ul>
<li>Sbírat bychom měli květy, které ještě <strong>nejsou úplně rozvité</strong>, ale určitě bychom si měli počkat na hezké suché počasí.</li>
<li>Květy otrhejte a rozprostřete stonky vzhůru do lísek nebo na síta, která jste předem vyložili čistým papírem.</li>
<li>Takto nechte květy ležet přes noc, kdy pěkně zavadnou a navíc se z nich většina hmyzu odstěhuje jinam.</li>
<li>Před samotným sušením ze všech květů postupně odstříhejte všechny silnější stonky.</li>
<li>Sušení by mělo <strong>být rychlé</strong>, ideální je teplota 35 až 40 ºC, při pomalejším sušení je velká pravděpodobnost, že květy zhnědnou.</li>
<li>Nasušenou drogu přesypte do sklenic s pevným uzávěrem a skladujte v tmavé místnosti.</li>
</ul>
<p><img src="https://anetabenediktova.cz/wp-content/uploads/2022/06/bylinny-caj-300x200.jpg" alt="" /></p>
<h3>Mast, kloktadlo a inhalace</h3>
<p>Prvním zajímavým receptem je <strong>kloktadlo</strong> na zanícený nosohltan nebo mandle, kdy 5 gramů sušené bylinky nasypete do studené vody, přivedete k varu a ihned odstavíte. Kloktejte vychladlý a přecezený odvar.</p>
<blockquote>
<p>Na drobná <strong>hnisavá kožní onemocnění</strong> můžete vyzkoušet tuto <strong>mast</strong>: Svařte 10 gramů sušených květů se dvěma lžícemi vepřového sádla ( nesoleného) ,směs přeceďte přes čisté plátýnko, nalijte do sklenice a samozřejmě nechte vychladnout.</p>
</blockquote>
<p>Na chronický <strong>zánět čelních dutin</strong>, <strong>hučení v uších</strong> i bolest hlavy pomáhá <strong>inhalace</strong> ze 4 hrstí sušených květů černého bezu, 2 kávových lžiček mletého kmínu a 3 stroužků nakrájeného česneku. Všechny ingredience dejte do hrnce s vodou, 1-2 minuty povařte a pak inhalujete</p>
<h3>Čerstvé květy černého bezu se uplatní i v kuchyni</h3>
<p><strong>Chutný recept</strong></p>
<ul>
<li>Z hladké mouky, vajec a piva si připravte hustší těstíčko, přidejte sůl a pepř, případně strouhaný sýr dle vlastního výběru.</li>
<li>Oprané květy berte jednotlivě za stonek, namočte v těstíčku a hned položte do rozpáleného oleje v pánvi.</li>
<li>Během smažení první strany květu odstřihávejte stonky a pak dosmažte i druhou stranu.</li>
</ul>
<p>Takto připravené květy jsou výborné s novým bramborem, čerstvou pažitkou a rozpuštěným máslem. Milovníci sladkého mohou zkusit květy namáčet do těstíčka bez soli, pepře a sýru a po usmažení dochutit skořicovým cukrem.</p>
<h3>Sirup z bezových květů</h3>
<p>Domácí sirup z květů je vynikající jako sladidlo do čaje, zvláště při nachlazení. Mezi lidmi koluje spousta receptů, liší se poměrem květů, vody a cukru nebo přítomností kyseliny citronové. Někdo sirup před nalitím do sklenic povaří, jiní radí jenom mírně zahřát, aby se cukr rozpustil.</p>
<p>Tady je zajímavý recept:</p>
<ul>
<li>Na 25 květů budete potřebovat 1,5 litru vody, 1 citron a 1 kg hnědého nerafinovaného cukru (neničí léčebné účinky byliny jako cukr bílý).</li>
<li>Květy ponořte do vody, přidejte kolečka oloupaného citronu bez jader a nechte 24 hodin stát.</li>
<li>Potom tekutinu přeceďte přes plátýnko, přidejte cukr a chvíli povařte.</li>
<li>Ještě horký sirup přelijte do vyvařených sklenic nebo lahviček, než vychladnou, postavte je dnem vzhůru.</li>
</ul>
<p><strong>Listy černého bezu léčí klouby a kosti</strong></p>
<p>Obklady z čerstvých listů černého bezu velmi dobře působí na <strong>záněty Achillovy šlachy</strong>, různé pohmožděniny, ostruhy a nárůstky na patách či jiných kostech. Čerstvé listy mírně naklepejte, přiložte na postižené místo. Dobře obalte potravinářskou fólií a nechte působit přes noc.</p>
<p>Nyní máte mnoho inspirací, tak stačí jen vyrazit a sbírat!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/06/shutterstock_433410907.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2022-06-07T17:52:52+00:00$q$,$q$https://anetabenediktova.cz/leciva-sila-cerneho-bezu/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$astma-a-prirodni-lecba$q$,$q$Astma a přírodní léčba$q$,$q$„…navštívila jsem poradnu paní Anety Benediktové s tím, že roky užívám kortikoidové léky na astma a místo toho aby se můj stav zlepšoval, tak mi lékařka pouze postupně léky přidávala. Jednoho dne můj pohár trpělivosti přetekl a rozhodla jsem se své problémy s astmatem řešit přírodní cestou. Ta sice $q$,$q$<blockquote>
<p>„…navštívila jsem poradnu paní Anety Benediktové s tím, že roky užívám kortikoidové léky na astma a místo toho aby se můj stav zlepšoval, tak mi lékařka pouze postupně léky přidávala. Jednoho dne můj pohár trpělivosti přetekl a rozhodla jsem se své problémy s astmatem řešit přírodní cestou. Ta sice nebyla komfortní, ale účinek se dostavil celkem rychle. Děkuji paní Benediktové a vašim bylinkám Serafin….“</p>
</blockquote>
<p>Tolik citace z dopisu, který opravdu zahřeje u srdce. V České republice žije více jak milión lidí s astmatem. Toto onemocnění je <strong>klasickou medicínou</strong> považováno za<strong> nevyléčitelné,</strong> a stejně tak jako ostatní nemoci je<strong> oddělováno na samostatnou chorobu</strong>. Z <strong>celostního hlediska</strong> se však jedná o jeden <strong>z projevů alergií</strong>, jehož projevy jsou silnější či slabší podle psychického a fyzického stavu člověka.</p>
<p>A zde se dostáváme k dalšímu onemocnění, kde medicína tvrdí, že je nevyléčitelné, a to jsou <strong>alergie</strong>. <strong>Obojí je možné vyléčit.</strong> Naše tělo je dokonalý mechanismus, který se umí sám opravit, jen na to potřebuje prostor a podmínky. Ty mu však často nejsme ochotni dát. Nejsme ochotni udělat ústupky z našeho komfortního života s cukrem, alkoholem a dalšími &#8222;mňaminkami&#8220;. Nejsme ochotni změnit své vnímání a pracovat na svých stresových reakcích. A tak se <strong>stále dokola potácíme v kruhu nemocí</strong>, v kruhu alergií, poruch imunity a také astmatu.</p>
<h2>Kde alergie začíná</h2>
<p>Klasická medicína většinou uvádí, že důvody a vznik alergií není přesně znám. Z pohledu přírodní medicíny pracujeme s tím, že základem alergií jsou <strong>problémy ve střevech, a také v játrech</strong>.</p>
<p>Střevní výstelku tvoří miliarda buněk epitelu, který vytváří bariéru mezi vnějším prostředím a vnitřkem střeva. <strong>Střeva</strong> jsou domovem triliónů bakterií, které hrají důležitou roli nejenom při štěpení živin, ale hlavně ovlivňují efektivnost našeho <strong>imunitního systému</strong>.</p>
<p><strong>Jemnou výstelku střev lze velmi jednoduše poškodit</strong>. Nejčastějšími viníky bývají <strong>alkohol, antibiotika, analgetika a jiné léky</strong>. Potom je tu také skutečnost, že konzumujeme příliš mnoho <strong>lepku, cukru a mléka</strong>. Tyto všechny složky potravy mají velmi silný alergenní potenciál. Výsledkem je, že některé bílkoviny z naší stravy, které se normálně štěpí na základní částice – aminokyseliny, jsou schopny <strong>přecházet poškozenou střevní stěnou</strong> přímo do krevního řečiště. Tam je imunitní systém identifikuje jako cizorodou látku a napadne je. Takto vznikají potravinové alergie, ale celá řada jiných typů alergií jako třeba na pyly, trávy či zvířecí srst. Zvláštní oblastí jsou vrozené typy silných potravinových alergií např. na ořechy. Ty aktivují imunoglobuliny IgE, a tato reakce může mít fatální následky.</p>
<h2>Co to je astma</h2>
<p>Onemocněním zvaným astma trpí milióny lidí na celém světě. Projevuje se <strong>nepříjemnými stavy dušnosti, které přicházejí jak v klidu, tak při námaze.</strong> Je doprovázeno postupným zmenšováním kapacity plic, a tím způsobuje problémy s okysličováním celého organismu. Znamená rovněž zvýšenou <strong>zátěž pro srdce.</strong> Klasická medicína pacientům s astmatem nabízí pouze potlačování příznaků, a to hlavně léky s obsahem kortikoidů. Přírodní medicína se snaží léčit příčiny. Že to nejde? Ale jde!</p>
<p><strong>Astma není plicní</strong> nebo průduškové onemocnění v pravém smyslu slova. Astma je vlastně nervová choroba, tedy onemocnění nervového systému. <strong>Práce celého dýchacího systému je řízena nervem</strong>, který se česky jmenuje <strong>bloudivý.</strong> Bloudivý proto, že z mozku prochází přes mnoho struktur a orgánů, vine se kolem průdušek, a nakonec se dostává až do žaludku. Je důležité rozlišovat, zda se jedná o astma bronchiální či alergické. <strong>Bronchiální astmatici trpí nejvíce v zimě, zatímco alergické astma se naplno projevuje v jarních měsících, v pylové sezóně</strong>. Nepříjemné je, že nemocný netuší, ve které chvíli se záchvat objeví.</p>
<h2>Co tedy dělat?</h2>
<p>Imunita a s ní spojené <strong>alergické reakce těla výrazně ovlivňuje stav našich střev</strong>. Proto při přírodní léčbě astmatu je důležité dát na začátku do pořádku střeva, střevní sliznici a střevní mikroflóru. Někdy se totiž ze střeva mohou uvolňovat toxiny, které pak oslabují funkci dalších tkání nebo se skrze porušenou střevní stěnu do organismu dostávají různé alergeny. <strong>Funkce dýchacího ústrojí přímo souvisí se stavem střeva.</strong> Toto ví nejenom čínská medicína, ale i všechny tradiční přírodní medicíny.</p>
<p>Při odstraňování astmatických problémů je tedy třeba soustředit se na správnou funkci střev, jater a nervového systému. Je důležité zbavit tyto orgány mikrobiální, plísňové zátěže a také těžkých kovů.</p>
<h3>Strava</h3>
<p>První krok, který můžeme udělat okamžitě je upravit svůj jídelníček. <strong>Existuje 5 základních druhů potravin, které podporují rozvoj astmatu:</strong></p>
<p>Kravské mléko</p>
<p>Přidaný cukr</p>
<p>Uzeniny</p>
<p>Lepek</p>
<p>Alkohol</p>
<p><strong>Žádná z výše uvedených potravin není nutná pro náš život</strong>. Kravské mléko a výrobky z něj můžeme nahradit mlékem ovčím, kozím či rostlinným. Pro běžný život našemu tělu naprosto dostačuje cukr, který je přirozeně obsažený v ovoci. Přidaný cukr v zákuscích, sušenkách či nápojích nám jen škodí.</p>
<p>Lepek velmi zatěžuje střeva a imunitu. Jeho maximální omezení a přechod na <strong>přirozeně bezlepkové</strong> potraviny nám jen pomůže.</p>
<h3>Bylinami ke zdraví</h3>
<p>Při léčbě astmatu je nutné užívat byliny, které budou současně působit na všechny orgány, které se podílí na rozvoji této choroby.</p>
<blockquote>
<p><strong>Andělská kůra Serafin – Astma </strong></p>
<p>Střídejte po dni čaje <a href="https://serafinbyliny.cz/produkt/pylergen-sypany-caj_219">PYLERGEN</a>, <a href="https://serafinbyliny.cz/produkt/prudusky-sypany-caj_218">PRŮDUŠKY</a>, <a href="https://serafinbyliny.cz/produkt/jatra-sypany-caj_162">JÁTRA</a>.</p>
<p>K tomu denně užívejte: tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/cerny-rybiz-tinktura-z-pupenu_154">ČERNÝ RYBÍZ</a> a přírodní kapsle <a href="https://serafinbyliny.cz/produkt/pylergen_127">PYLERGEN</a> a přírodní kapsle <a href="https://serafinbyliny.cz/produkt/pohoda_126">POHODA</a></p>
</blockquote>
<p>Je velmi důležité užívat celou kůru společně minimálně 3 měsíce, vždy s týdenní pauzou do jednom měsíci. Úprava stravy se neodmyslitelnou součástí léčby.</p>
<h3>Astma a psychika</h3>
<p><strong>Stres působí nejen na disharmonii</strong> našeho organismu, ale také <strong>oslabuje imunitní systém</strong>, mění chemické procesy v organismu, působí na vylučování látek, které pak mají vliv na chod našeho imunitního a <strong>nervového systému.</strong> Proto bychom v rámci léčby neměli zapomenout na preparát k odstranění stresu (kapsle Pohoda).</p>
<p><strong>Uvolněný, relaxovaný a nestresovaný organismus</strong> v dobrém emocionálním rozpoložení dokáže téměř všechny problémy <strong>krásně vyřešit sám</strong> i bez pomoci zvenčí. Bohužel takový stav se prakticky nikomu nepodaří nastolit. Je však důležité na tom pracovat například pomocí různých seminářů a kurzů. Podívejte se <a href="https://anetabenediktova.cz/sluzby/kurzy-a-seminare/">zde</a></p>
<p>V neposlední řadě můžeme zmínit ještě jeden &#8222;lék &#8222;– a tím je <strong>upřímný smích</strong>, který skutečně léčí. Smích „od srdce“ masíruje bránici i všechny vnitřní orgány, uvolňuje veškeré blokace a podporuje samo detoxikační procesy v těle.</p>
<p>Přeji vám hluboký a klidný dech!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/05/astma-a-byliny.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-05-02T07:13:18+00:00$q$,$q$https://anetabenediktova.cz/astma-a-prirodni-lecba/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$padani-vlasu-po-covidu$q$,$q$Padání vlasů po covidu$q$,$q$Už je to více jak dva roky, co žijeme s nemocí Covid 19. Postupně začínáme zjišťovat, že zvládnutí akutní části tohoto onemocnění je jedna kapitola, ale následky zvané post covid syndrom je kapitola druhá. Jedním z častých příznaků tohoto syndromu je nadměrné padání vlasů. Proč vlasy padají? Vědci z$q$,$q$<p>Už je to více jak dva roky, co žijeme s nemocí Covid 19. Postupně začínáme zjišťovat, že zvládnutí akutní části tohoto onemocnění je jedna kapitola, ale následky zvané <b>post covid syndrom</b> je kapitola druhá. Jedním z častých příznaků tohoto syndromu je nadměrné padání vlasů.</p>
<h2>Proč vlasy padají?</h2>
<p>Vědci z celého světa postupně dělají různé studie post covid syndromu a jeho projevů. Zjistilo se, že padání vlasů postihuje více ženy než muže, ale odpověď na otázku proč, ještě není. Stejně tak není přesná odpověď na otázku, proč vlasy padají. Předpokládají se dva základní faktory. <b>Stres a ztráta vitamínů a minerálů.</b></p>
<h2>Stres</h2>
<p>To, že celé <b>dva roky jsme všichni žili v neobvyklém stresu </b>je jasné. To, že nemoc covid 19 jako taková je pro náš organismus velmi zatěžující a stresující je jasné také. Většina z nás to zažila na vlastní kůži. Nicméně stres je běžnou součástí našich životů. Musíme se vyrovnávat s každodenními nároky v zaměstnání, manželství, v chodu domácnosti, ve výchově dětí atd. Tyto nároky bývají stresující už jen samy o sobě, avšak občas bývají ještě zhoršovány dalšími událostmi jako je třeba pandemie.</p>
<p>Je prokázáno, že <b>dlouhodobý, chronický stres</b> dokáže v našem těle podnítit vznik celé řady onemocnění, a to zejména kardiovaskulární, poruchy imunity a v neposlední řadě také <b>snížení kvality a vypadávání vlasů.</b> Může za to celá řada hormonálních pochodů v těle, na kterých se podílí náš <b>limbický systém, štítná žláza i nadledvinky. </b>Při dlouhodobém stresu také dochází k zatěžování a dysfunkci trávicího traktu zejména střev, žlučníku a slinivky.</p>
<h2>Ztráta vitamínů a minerálů</h2>
<p>Pokud je náš organismus zatížen těžkou nemocí přirozeně se<b> zvyšují jeho nároky na potřebu minerálů a vitamínů</b>. Při stresové reakci spotřebováváme zejména vitamíny<b> řady B, Hořčík, ale i Selen, Vápník a vitamín C.</b> Všechny tyto prvky jsou potřebné mimo jiné pro dobrou kvalitu naší kůže, vlasů, zubů a dalších částí těla. Při nemoci a stresu začnou chybět a to se následně projeví třeba vypadáváním vlasů nebo ztrátou jejich kvality.</p>
<h2>Nepropadejte panice</h2>
<p>Vše má své řešení, a to i vypadávání vlasů po covidu. Z logiky výše napsaného vyplývá, že je nutné našemu organismu <b>dodat chybějící vitamíny a minerály. </b>Není však vitamín jako vitamín. Pokud chceme, aby se rychle a účinně dostaly v našem těle tam kam mají a fungovaly tak jak mají, tak je potřebné dodržet několik zásad</p>
<p>a) Vitamíny by měly být <b>z přirozených zdrojů</b> jako je ovoce, zelenina, plody rostlin či stromů, a to <b>koncentrované ve formě extraktu.</b> Potom je jejich vstřebatelnost a účinnost vysoká.</p>
<p>b) Minerály a vitamíny <b>se vzájemně potřebují </b>k dobré vstřebatelnosti. Například vitamín A potřebuje zinek, hořčík potřebuje vápník apod.</p>
<p>c) Dobrá <b>kvalita střeva a střevní sliznic</b>e je základem dobrého zpravování a využití vitamínů a minerálů. Proto pokud dodáváme potravinové doplňky na vlasy je potřeba k nim užívat byliny na podporu funkce střev jako je třeba Pampeliška lékařská</p>
<p>d) <b>Fungující játra</b> zajistí správné štěpení a transport vitamínů a minerálů</p>
<h2>A co dál?</h2>
<p>Dalšími kroky, kterými můžeme podpořit svoji „korunu krásy“ je <b>strava, která naše tělo nepřekyseluje</b>. Doporučujeme vynechat průmyslově zpracované potraviny, výrobky z bílé mouky, přidaný cukr a také alkohol. <b>Zvyšte podíl ovoce a zeleniny</b>, i když ony sami o sobě nám potřebné množství vitamínů a minerálů při padání vlasů nedodají. Působí však v našem těle pozitivně na celou řadu pochodů a funkcí.</p>
<p>Významnou pomocí je cílená <b>relaxace, <a href="https://anetabenediktova.cz/sluzby/kurzy-a-seminare/uvolneni-stresu-zaklad-zdravi-jak-na-to/">uvolnění pohybem, dechem</a></b> či jinými metodami.</p>
<p>A nezapomeňte, že své vlasy můžete podpořit i skvělými <b>bylinnými přípravky na zevní užití </b>jako je třeba výrobek<b> <a href="https://serafinbyliny.cz/produkt/vlasy-s-proti-vypadavani-vlasu_479">Vlasy S</a></b>, jehož recepturu sestavila Prof. Strunecká.</p>
<p>Vkročte do slunného jara s bujnou kšticí! Už víte jak na to.</p>
<p>Můj tip pro vaši bujnou kštici: čaj <a href="https://serafinbyliny.cz/produkt/vlasy-porcovany-caj_445">Vlasy</a> + kapsle <a href="https://serafinbyliny.cz/produkt/vlasynehty_111">Vlasy+nehty</a> + kapsle <a href="https://serafinbyliny.cz/produkt/multiserafin-s-vitaminem-d_109">Multiserafin</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/04/vlasy-padani.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-04-18T17:52:04+00:00$q$,$q$https://anetabenediktova.cz/padani-vlasu-po-covidu/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$gemmoterapie-lecba-pupeny-rostlin$q$,$q$Gemmoterapie – léčba pupeny rostlin$q$,$q$Každý rok na jaře jsme všichni svědky velkého zázraku přírody. Zdánlivě suché semínko povalující se na zemi pokropené kapkami prvního jarního deště se za svitu slunce začíná zvětšovat a ožívat a během pár dní se z něj velkou silou dere malý zelený klíček. Stejně tak stromy na první pohled vypadající$q$,$q$<blockquote>
<p>Každý rok na jaře jsme všichni svědky<strong> velkého zázraku přírody</strong>. Zdánlivě suché semínko povalující se na zemi pokropené kapkami prvního jarního deště se za svitu slunce začíná zvětšovat a ožívat a během pár dní se z něj velkou silou dere <strong>malý zelený klíček</strong>. Stejně tak stromy na první pohled vypadající jako suché, naberou do svých kořenů ze země <strong>životadárnou mízu</strong> a vlásečnicemi pod kůrou kmene jí vedou směrem k větvím až do jejích konečků a <strong>do mladých pupenů,</strong> které se začnou rozvíjet.</p>
</blockquote>
<p>Už naši předci věděli, že <strong>v mladých pupenech, klíčcích a poupatech je ukrytá nesmírná síla</strong>, <strong>která umí léčit</strong>. Pupeny a poupata jsou jako zárodečné buňky nasycené informacemi o všech částech rostliny, tedy o jejím plodu, listu, kořeni i kůře. Zároveň jsou <strong>bohaté na minerály, vitamíny, enzymy</strong> a celou řadu látek prospěšných lidskému tělu.</p>
<p>Ve starověké čínské medicíně najdeme zmínky o léčbě extrakty z mladých výhonků rostlin. Na Ukrajině se tradičně nakládají mladá poupata černého rybízu na tinkturu, která je užívá v zimě na podporu imunity a na to, aby lidé na jaře neměli jarní alergie.</p>
<blockquote>
<p>Novodobou historii tohoto oboru zvaného gemmoterapie (léčba pupeny a poupaty rostlin) začal psát Dr. Paul Henry z Bruselu, který v roce 1952 jako první připravil výtažek z pupenů břízy. Dr. Paul Henry si po stovkách experimentů s rostlinnými látkami uvědomil, že <strong>každá rostlina ukládá do pupenů to nejcennější, co má</strong> pro svůj další růst, a pupeny jsou tak výjimečnou částí každé rostliny a mohou tedy obsahovat nejvíce léčivých látek z celé rostliny.</p>
</blockquote>
<p>Dr. Henry po vyzkoušení výtažků z pupenů zjistil, že je nejlepší k <strong>užívání potence 1:10</strong> a dávkování podle váhy klienta. <strong>Tedy jedna kapka takto potencovaného extraktu na jedno kilo váhy a den.</strong> Tuto dávku je nutné rozdělit na 2-3 části za den. Popsané dávkování je velmi přesné a dovoluje tinktury z pupenů užívat i malým dětem zhruba od tří let věku. Důležité je myslet na to, že v případě <strong>používání u dětí</strong> je nutné požadovanou dávku nakapat do <strong>malého množství horké vody,</strong> aby se odpařil zbytkový alkohol. Po vychladnutí dítěti teprve podat.</p>
<p>U nás se o gemmoterapií a jejím praktickým využitím začali zajímat nejznámější představitelé alternativní medicíny, <strong>Josef A. Zentrich a ing. Jiří Janča</strong>, kteří jako první o této metodě napsali v roce 1997.</p>
<p>Tinktury z pupenů se na našem trhu dnes již dají běžně koupit, nicméně Evropská a následně Česká legislativa tyto přírodní přípravky neuznává, naopak u některých druhů je nově zákaz jejich výroby. Bylinné přípravky z pupenů byly desetiletí s úspěchem využívány v přírodní medicíně a můžeme se jen domnívat komu takové zákazy prospívají. To, že zákazník na tinktuře z pupenů nenajde žádnou informaci o jejím účinku nebo jen minimální je jen výsledek všech právních předpisů a nařízení.</p>
<h2>Jak extrakty z pupenů užívat?</h2>
<p>Dříve se gemmoterapie doporučovala užívat takovým postupem, že se nejdříve využívala jedna lahvička tinktury z pupenů břízy jako silný drenážní, čistící prostředek, a následně se nasadila tinktura z pupenů rostliny, která měla cíleně působit přímo na daný problém.</p>
<p>V současné době však řada lidí trpí těžkými systematickými chorobami a drenáž břízou jim často způsobí silnou reakci těla. Podle posledních zkušeností<strong> je nejvýhodnější tinktury z pupenů zařazovat do komplexní léčby společně minimálně s jedním bylinným čajem</strong>, který dělá současně mírný drenážní efekt, ale zároveň i čistící a léčebný. Nedoporučuje se současně užívat více jak dvě tinktury z pupenů.</p>
<p>Gemmoterapii můžeme využívat s velkým úspěchem jako <strong>preventivní bylinnou léčbu</strong>. Velké opodstatnění má její užívání právě v jarních měsících, kde je organismus přirozeně nastaven na očistu a regeneraci.</p>
<p>Zajímavostí v gemmoterapii je ta skutečnost, že <strong>tinktura v sobě obsahuje informace o všech částech rostliny.</strong> Takže například Jirovec maďal – kaštan. Jeho květy se tradičně používaly do čajů působících na cévy a oběhový systém a plody na výrobu mastí a extraktů na klouby. <strong>V tinktuře z pupenů Kaštanu je obojí účinek.</strong></p>
<p><img src="https://anetabenediktova.cz/wp-content/uploads/2022/04/pupeny-3-300x225.jpg" alt="" /></p>
<h2>Nejznámější tinktury z pupenů a jejich účinky</h2>
<p><strong>Bělotrn</strong>– zlepšuje vedení vzruchu po nervech, takže je vhodný při tzv. <strong>ústřelu páteře</strong>. Tedy všude tam, kde nervy bolí a potřebují pomoci. Platí to i u <strong>trojklanného nervu</strong> anebo jako podpůrná léčba u roztroušené sklerózy či <strong>Parkinsonovy choroby</strong>. Jsou s ní velké úspěchy při podpoře léčby <strong>boreliózy</strong> ve III. stádiu nebo <strong>post-covidového syndromu</strong>. Nesmí se kombinovat s léky z kategorie digitalis.</p>
<p><strong>Borůvka</strong> – snižuje <strong>hladinu cukru v krvi</strong> a napomáhá k lepšímu vidění. Je to skvělá tinktura pro diabetiky na ochranu jejich <strong>zraku</strong>.</p>
<p><strong>Brusinka</strong> – působí v oblasti ledvin a <strong>močového měchýře</strong> zejména jako <strong>prevence</strong> proti zánětu či inkontinenci.</p>
<p><strong>Bříza</strong> – je to velmi silná očistná tinktura. <strong>Čistí játra a umí velmi dobře odvodnit.</strong> Při jejím užívání může nastat detoxikační reakce na kůži, moč i stolice mohou více zapáchat, ale jedná se o přirozený proces</p>
<p><strong>Černý jeřáb</strong> – skvěle umí <strong>harmonizovat funkci štítné žlázy</strong>, a to směrem nahoru i dolů. Z tohoto důvodu jí mohou užívat i lidé s hyperfunkcí i s hypofunkcí. Působí velmi dobře i při autoimunitním zánětu. Je nutné jí užívat dlouhodobě.</p>
<p><strong>Černý rybíz</strong> – má silné protizánětlivé účinky, podobně jako kortikoidy, ale v přírodní formě. Nejčastěji se užívá při <strong>přírodní léčbě alergií</strong>, a to preventivně, ale i v akutní fázi</p>
<p><strong>Česnek medvědí</strong> – významně <strong>čistí cévy</strong>, takže je vhodný při a<strong>rterioskleróze a jako prevence mozkové mrtvice či jiné kardiovaskulární choroby</strong>. Snižuje <strong>krevní tlak</strong>, mírně ředí krev a působí protizánětlivě.</p>
<p><strong>Divizna</strong> – skvělá bylina při <strong>zánětech průdušek a plic</strong>. Velmi se osvědčuje u dětí. Napomáhá <strong>odkašlat a tlumí zánět</strong>. U dětí je nutné požadovanou dávku nakapat do malého množství horké vody, aby se odpařil zbytkový alkohol. Po vychladnutí dítěti teprve podat.</p>
<p><strong>Dub</strong> – působí protizánětlivě zejména na sliznice v <strong>oblasti střev</strong>. V tomto případě je také nutné požadovanou dávku nakapat do malého množství horké vody, aby se odpařil zbytkový alkohol. Dub velmi dobře odstraňuje<strong> záněty dásní a paradentózu</strong></p>
<p><strong>Gotukola</strong> – zlepšuje <strong>prokrvení mozku</strong> a celkově působí na <strong>roztažení cév.</strong> Má velmi pozitivní vliv na <strong>myšlení.</strong> Je vhodná pro starší lidi</p>
<p><strong>Hloh</strong> – jemným způsobem s<strong>nižuje krevní tlak</strong> a <strong>zmírňuje bušení srdce a rychlý srdeční rytmus.</strong> Může se užívat i s léky na tlak a srdce, jen je nutné krevní tlak průběžně kontrolovat.</p>
<p><img src="https://anetabenediktova.cz/wp-content/uploads/2022/04/cerny-jerab-pupeny-300x225.jpg" alt="" /></p>
<p><strong>Jeřáb ptačí</strong> – přirozeným způsobem podporuje tvorbu estrogenů v ženském těle. Používá se na podporu<strong> plodnosti, úpravu menstruace</strong> nebo na problémy spojené s <strong>klimakteriem.</strong></p>
<p><strong>Jinan</strong> – Ginkgo biloba je rostlina, která umí velmi dobře působit na <strong>roztažení cév.</strong> Její užívání je nutné dlouhodobé. Zlepšuje <strong>prokrvení rukou a nohou,</strong> občas dokáže odstranit <strong>hučení v uších,</strong> pokud je způsobeno staženými cévami. Používá se i na prokrvení <strong>zablokované páteře.</strong></p>
<p><strong>Kaštan</strong> – užívá se při <strong>křečových žilách a hemeroidech</strong>, jelikož dokáže zmírnit až vyléčit jejich zánět. Je skvělý i při bolestech kloubů.</p>
<p><strong>Kopřiva</strong> – universální bylina, která umí<strong> čistit játra, ledviny a krev.</strong> Podpoří slinivku i slezinu. Obsahuje látky, které zlepšují hladinu<strong> železa v krvi</strong>. Nejsou na ní takové reakce jako na břízu</p>
<p><strong>Kotvičník</strong> – je to bylina s „mužskou energií“. Napomáhá tvorbě<strong> testosteronu</strong>, zlepšuje <strong>kvalitu a množství spermií.</strong> Při sportu zlepšuje<strong> výkon a podporuje růst svalů.</strong> Není moc vhodná pro ženy.</p>
<p><strong>Lichořeřišnice</strong> – úžasná univerzální bylina na záněty všeho druhu. Nejvíce působí <strong>na záněty močového měchýře a průdušek</strong>. Také se užívá u<strong> gynekologických zánětů</strong>. Stejně jako Divizna je vhodná i pro děti.</p>
<p><strong>Lípa</strong> – uvolňuje a uklidňuje zejména různé formy <strong>dětských strachů</strong>. Opět nezapomeňte na to, že u dětí je nutné požadovanou dávku nakapat do malého množství horké vody, aby se odpařil zbytkový alkohol. Po vychladnutí teprve dítěti podat.</p>
<p><strong>Měsíček</strong> – extrakt z pupenů chrání <strong>ženské pohlavní orgány před záněty a výtoky</strong>. Je to hodně preventivní bylina, kterou je dobré užívat po zvládnutí akutního zánětu.</p>
<p><strong>Morušovník</strong> – užívá se na úpravu kolísající <strong>hladiny cukru v krvi</strong>, a také na podporu při <strong>odvykání závislosti na sladkém</strong>, na cukru</p>
<p><img src="https://anetabenediktova.cz/wp-content/uploads/2022/04/licho-poupe-2-225x300.jpg" alt="" /></p>
<p><strong>Ořešák</strong> – silný bojovník proti <strong>střevním parazitům</strong> a proti zánětům tlustého střeva.</p>
<p><strong>Oskruše</strong> – působí proti křečovým žilám, ale zejména proti <strong>cévním a lymfatickým otokům</strong></p>
<p><strong>Ostropestřec</strong> – základní bylina na <strong>regeneraci jaterní buňky</strong>. Zlepšuje <strong>trávení,</strong> podporuje funkce <strong>žlučníku a slinivky</strong>. Je to nejúčinnější forma pro užívání byliny Ostropestřec mariánský.</p>
<p><strong>Pupalka</strong> – účinně pomáhá proti <strong>premenstruačnímu syndromu.</strong> V tomto případě jí stačí užívat pouze několik dní před menstruací. Dokáže také snížit projevy <strong>klimakteria.</strong></p>
<p><strong>Rakytník</strong> – podporuje <strong>imunitu</strong> v dlouhodobém horizontu. Má uklidňující účinek na <strong>sliznice žaludku</strong> a celého trávicího traktu</p>
<p><strong>Rozchodnice</strong> – <strong>zmírňuje stres a podporuje kognitivní funkce mozku.</strong> Zlepšuje učení a soustředění. Je vhodná i pro děti s <strong>poruchou učení a soustředění</strong>. Opět nezapomeňte na to, že u dětí je nutné požadovanou dávku nakapat do malého množství horké vody, aby se odpařil zbytkový alkohol. Po vychladnutí teprve dítěti podat.</p>
<p><strong>Šišák</strong> – uvolňuje <strong>stresové napětí a snižuje hladinu cholesterolu</strong>, který je zvýšen vlivem dlouhodobého stresu.</p>
<p><strong>Třezalka</strong> – bylina se <strong>sedativním a protizánětlivým účinkem</strong>. Celkově uklidňuje a<strong> zlepšuje spánek</strong> a celkové usínání. Působí i na <strong>záněty nervů</strong> zejména míšních nervů a trojklanného nervu. Nesmí se kombinovat s antidepresivy</p>
<p><strong>Tužebník</strong> – Mírně ředí krev, snižuje hladinu kyseliny močové v krvi a působí proti bolesti zánětlivých kloubů. Používá se při <strong>onemocnění Dna</strong>, ale i jako prevence proti <strong>trombóze</strong>.</p>
<p><strong>Vřes</strong> – podporuje funkce <strong>ledvin</strong> a zároveň je čistí. Umí vyloučit <strong>močový písek</strong> z ledvin i močového ústrojí.</p>
<p><strong>Zlatobýl</strong> – základní bylina pro naše <strong>ledviny</strong>. Podporuje jejich funkce, působí proti jejich <strong>vyčerpání, zánětu.</strong> Mírně snižuje krevní tlak způsobený stresem a vyčerpáním ledvin.</p>
<p>Nyní už znáte účinky základních gemmoterapeutik. Nezapomeňte při jejich volbě vždy zvolit i odpovídající <a href="https://serafinbyliny.cz/e-shop/bylinne-caje_3">bylinný čaj</a>, aby léčba byla úspěšnější.</p>
<p>Všechny zmiňované přípravky najdete na <a href="https://serafinbyliny.cz/e-shop/bylinne-tinktury_12/pupenove-bylinne-tinktury_13">www.serafinbyliny.cz</a> včetně bylinných čajů. Tato firma vytváří produkty v celkovém konceptu, takže se vzájemně skvěle doplňují!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/04/pupeny-kastan.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$,$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-04-09T17:43:07+00:00$q$,$q$https://anetabenediktova.cz/gemmoterapie-lecba-pupeny-rostlin/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$borelioza-ci-post-covid-syndrom$q$,$q$Borelióza – novodobá pandemie.$q$,$q$Většina lidí prošla onemocněním covid 19, a to s těžším či lehkým průběhem. Někdo měl tak lehký průběh, že ani nevěděl, že tímto onemocněním prochází. Nicméně po určité době, která může trvat až několik měsíců, se u vás mohou začít náhle objevovat různé zdravotní potíže. Onemocnění Covid 19 je zcela$q$,$q$<p>Většina lidí prošla onemocněním covid 19, a to s těžším či lehkým průběhem. Někdo měl tak lehký průběh, že ani nevěděl, že tímto onemocněním prochází. Nicméně <strong>po určité době</strong>, která může trvat až několik měsíců, se u vás mohou začít náhle <strong>objevovat různé zdravotní potíže</strong>.</p>
<blockquote>
<p>Onemocnění Covid 19 je zcela nové a stále prochází zkoumáním ve vědeckých laboratořích, a to nejenom konkrétně průběh nemoci, ale i jeho následky, tzv. post covid syndrom.</p>
</blockquote>
<p>Velmi nepříjemnou komplikací této infekce je fakt, že umí v těle <strong>aktivovat tzv. spící viry a bakterie. </strong> To jsou takové, se kterými se náš organismus v minulosti setkal, imunitní systém na ně dobře zareagoval a většinu jich zlikvidoval. Zbytky pak zůstaly v těle bez toho, aniž by mu škodily. Imunitní systém je bez problémů uhlídá, aby nám netropily neplechu.</p>
<p>O jakých virech a bakteriích mluvíme? Jsou to zejména <strong>herpes viry, EB virus, chlamýdie a borelie.</strong> A právě na poslední zmíněné se nyní zaměříme.</p>
<blockquote>
<p>Důležité je, že k reaktivaci virů a bakterií může dojít nejenom proděláním této nemoci, ale podle posledních výzkumů k němu dochází i po očkování, a to až několik měsíců po něm.</p>
</blockquote>
<h2><strong>Co to je Lymská borelióza</strong></h2>
<p>Lymská borelióza je onemocnění, které je způsobeno minimálně <strong>třemi druhy bakterií Borrelia</strong>. Toto onemocnění se vyskytuje zejména v severní Americe a Evropě. Bakterie žijí v krvi drobných zvířat. Jedná se zejména jedná o myši, hraboše, zajíce, veverky, krtky, ale i vysokou lesní zvěř.</p>
<p>Hlavním <strong>přenašečem boreliózy jsou klíšťata</strong>. Přenašeči, ale méně častí, jsou komáři, ovádi, blechy a mouchy.</p>
<p>Příznaky a průběh boreliózy se dělí do třech stádií. Toto rozdělení je pouze obecné, jelikož se mohou zároveň objevit i příznaky všech stádií.</p>
<h3><strong>První stádium boreliózy</strong></h3>
<p>zarudnutí na kůži, často s centrálním vyblednutím, které může vycházet z místa vpichu. Dalším příznakem může být zvětšení okolních lymfatických uzlin. Toto zarudnutí vzniká v průměru za 1 týden od přisátí klíštěte.</p>
<h3><strong>Druhé stádium boreliózy</strong></h3>
<p>začíná většinou za 2 až 12 týdnů po přisátí klíštěte, trvá několik týdnů a vymizí obvykle do tří měsíců po nákaze. Může se projevit jako <strong>neuroborelióza</strong>. Jejími projevy mohou být značně proměnlivé bolesti po celém těle, bolesti hlavy, periferní obrna nejčastěji lícního nervu, zánět mozkových blan a mozku. V druhém stádiu se často vyskytují <strong>bolesti kloubů a svalů</strong>. Nejčastěji postiženými <strong>klouby bývají kolena</strong>.</p>
<h3><strong>Třetí stádium boreliózy</strong></h3>
<p>začíná měsíce až roky po nákaze. Nejčastějšími příznaky bývají <strong>záněty mozku a míchy</strong>. Někdy tento stav může imitovat příznaky roztroušené sklerózy. Vyskytují se chronické bolesti zejména velkých kloubů a chronická únava.</p>
<h2><strong>Pozitivní protilátky nemusí nic znamenat</strong></h2>
<p>Protilátky k Lymské borelióze se promění v pozitivní teprve asi za měsíc po kontaktu s nakaženým klíštětem. V určitých regionech má až 25 procent populace pozitivní protilátky, protože se s boreliózou setkalo a ani o tom nevědělo. Takže <strong>pozitivní test nemusí znamenat nic</strong>. Podstatně důležitější je, že kterékoli protilátky proti borelióze mohou navíc zůstat navýšené doživotně, a to i u úspěšně vyléčených pacientů.</p>
<h3>Pozor na falešně pozitivní testy!</h3>
<p>S fenoménem <strong>falešně pozitivních testů</strong> se setkávám ve své praxi čím dál častěji, a to nejen u boreliózy, al i u jiných nemocí, např. u hladiny PSA v krvi. O tom, jestli test je nebo není falešně pozitivní rozhoduje celá řada faktorů. Typ testu, použité látky na provedení testu, kolik lidí je celkově na stejnou chorobu v laboratoři testováno aj. Problematiku falešně pozitivních testů si můžete dohledat na internetu. Pokud si jí dobře nastudujete, tak zjistíte, že <strong>nemá smysl při bolestech kloubů hned podávat antibiotika s tím, že by to mohla být borelióza.</strong></p>
<p><strong>Příznaky lymské boreliózy, jsou takové, že se shodují s celou řadou příznaků jiných chorob, včetně post-covid syndromu.</strong> Bohužel často bývá pro lékaře jednodušší na základě jednoho ne stoprocentního testu stanovit diagnózu &#8222;lymská borelióza&#8220;, a to bez bližšího zkoumání a opakování testů. Nezřídka jsou pak lidé, kteří několik měsíců užívají antibiotika, která jejich tělo více zatěžují než by jim pomáhaly, a po jejich vysazení se stejně problémy vrátí.</p>
<h2>Léčba</h2>
<p>Základem úspěšné léčby boreliózy je správná diagnostika zejména správný typ laboratorního vyšetření a <strong>pouze v časném stádiu</strong> nemoci podávání <strong>vhodných antibiotik</strong>. <strong>Dlouhodobé podávání antibiotik nemá kýžený efekt a může organismus spíše poškodit</strong>. V dalších stádiích boreliózy přichází na řadu spíše <strong>přírodní léčba</strong> nebo tvz. symptomatická léčba – <strong>léčba příznaků</strong>.</p>
<blockquote>
<p>Pokud si shrneme všechny předchozí informace, tak je jasné, že ve spojení s post &#8211; covid syndromem se jedná o boreliózu ve druhém anebo třetím stádiu, kdy je <strong>neúčinné podávání antibiotik</strong>. Myšleno tedy přímo na boreliózu. Samozřejmě, pokud je v těle jiný bakteriální zánět, tak jsou antibiotika na místě.</p>
</blockquote>
<p>Velmi silným pomocníkem v tomto případě je přírodní léčba. Je důležité si však uvědomit, <strong>že stojíme proti mocnému „nepříteli“ a proto potřebujeme mocné „zbraně“.</strong></p>
<p>Těmi mohou být nejenom byliny, ale zejména <strong>přírodní houby.</strong> Jejich správná kombinace a dávkování pak patří do rukou odborníků na přírodní léčbu. Ti musí vždy individuálně posoudit u každého klienta, jeho celkový stav, prostředí, ve kterém žije, stravu, kterou jí a léky, které užívá.</p>
<p>Ráda vám nastavím léčbu přímo na míru. Objednat se můžete <a href="https://anetabenediktova.cz/kontakt/">zde</a></p>
<p><strong>Než si domluvíte termín, zkuste můj tip: </strong></p>
<p>Užívejte tuto mojí speciální Andělskou kúru:</p>
<p>pro může: <a href="https://serafinbyliny.cz/produkt/kliste-m_670">klíště M</a>, pro ženy <a href="https://serafinbyliny.cz/produkt/kliste-z_671">klíště Ž</a></p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/04/koleno-a-louka.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-04-04T16:52:57+00:00$q$,$q$https://anetabenediktova.cz/borelioza-ci-post-covid-syndrom/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$letosni-alergie-mohou-byt-jine$q$,$q$Letošní alergie mohou být jiné$q$,$q$Venku svítí sluníčko, pomalu se otepluje, přesto mnoho lidí zůstává doma s rýmou, dechovými obtížemi a údajně „virózami“. Ty však nemají tradiční průběh a často ani nejsou doprovázeny teplotami, pouze příznaky nachlazení a únavy. Je to i váš případ? Možná se nejedná o virózu ani o covid . Možná máte$q$,$q$<p>Venku svítí sluníčko, pomalu se otepluje, přesto mnoho lidí zůstává doma s rýmou, dechovými obtížemi a údajně „virózami“. Ty však nemají tradiční průběh a často ani nejsou doprovázeny teplotami, pouze příznaky nachlazení a únavy. Je to i váš případ? Možná se nejedná o virózu ani o covid . Možná máte jen jarní alergii, ale s jiným průběhem než jste zvyklý.</p>
<h2>Alergie ano či ne</h2>
<p>Všichni jsme prošli velmi náročným dvouletým obdobím covidu. To nás nesmazatelně poznamenalo na těle i na duši. <strong>Velké a dlouhé stresové vypětí,</strong> které bohužel nyní s ohledem na celosvětovou situaci pokračuje si zahrálo a <strong>zahrává s naším imunitním systémem</strong> a s naší zásobou <strong>životní energie</strong>.</p>
<blockquote>
<p>S virem Covid 19 jsme se setkali prakticky všichni. I když jsme neonemocněli nebo průběh nemoci byl jen slabý, tak náš organismus na něj určitě v nějaké fázi našeho života reagovat musel.</p>
</blockquote>
<p>Všichni už víme, že tento virus způsobuje respirační onemocnění, že silně oslabuje plíce a způsobuje v nich zánět. Co si však většinou neuvědomujeme je ta skutečnost, že do našeho těla se dostává tělesnými otvory. Těmi otvory je zejména nos a následně horní cesty dýchací. V této části těla máme receptory, které zachycují různé patogeny, drobné prachové částice i pyly a reagují na ně. Dávají našemu tělu zprávu co do něj přichází a jakou reakci má vyvolat.</p>
<p><strong>Covid 19 mimo jiné ničí právě tyto receptory.</strong> Oslabuje jejich funkce. Tímto způsobem se pak stane, že i když je už nemoc dávno za námi tak pokašláváme, stále nás něco dráždí a vyvolává nejenom kašel, ale i rýmu či slzení a pálení očí.</p>
<h2>Alergické projevy</h2>
<p>Receptory a sliznice v oblasti nosu a horních cest dýchacích náleží k imunitnímu systému. <strong>Alergie je neadekvátní reakce imunitního systému</strong>. To znamená, že on reaguje velkou reakcí na podněty, které tělu běžně neškodí. Těmi může být peří, prach a v tomto čase i pyly.</p>
<blockquote>
<p>Jestliže receptory nejsou úplně v pořádku, tak mohou vydávat falešné informace a v těle následně dochází k reakci, která se může projevovat jako rýma, kašel, pocity nachlazení.</p>
</blockquote>
<p>Ve většině případů se však <strong>v současné době jedná o alergické reakce</strong> na první jarní pyly. Tato reakce je <strong>umocněná celkovým vyčerpáním ze stresového období</strong>. Výsledkem všeho je, že hodně lidí si myslí, že má virózy, že jsou nemocní, ale ve skutečnosti se jedná o alergie, a to i osob, které alergiemi nikdy netrpěli.</p>
<p>Pokud nemáte vysoké teploty a trpíte rýmou, pálením očí, kašlem, únavou, zkuste si nasadit přírodní léčbu na alergie.</p>
<blockquote>
<p><strong>Můj Tip:</strong> kapsle <a href="https://serafinbyliny.cz/produkt/pylergen_127">Pylergen</a> v dávce 2 kapsle ráno a 2 kapsle odpoledne a k tomu tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/cerny-rybiz-tinktura-z-pupenu_154">Černého rybízu</a>. Při velké únavě přidejte ráno 2 kapsle <a href="https://serafinbyliny.cz/produkt/cordyceps_107">Cordyceps.</a></p>
</blockquote>

<p>Přeji vám krásné sluníčkové jaro</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/03/jarni-kvety.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-03-23T19:10:44+00:00$q$,$q$https://anetabenediktova.cz/letosni-alergie-mohou-byt-jine/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$702-2$q$,$q$Očista žlučníku karlovarskou solí$q$,$q$Základem dobrého metabolismu, imunity, hormonální činnosti, hubnutí, správné hladiny cukru a tuků v krvi a celkového zdraví jsou dobře fungující játra a s ním spojený žlučník. Jestliže máme zatížený žlučník a žlučovody nečistotami v podobě žlučových kamenů a tzv. bahna, odráží se to nejen na trávicí$q$,$q$<p>Základem<b> dobrého metabolismu, imunity, hormonální činnosti, hubnutí, správné hladiny cukru a tuků v krvi  a celkového zdraví</b> jsou dobře fungující játra a s ním spojený žlučník. Jestliže máme zatížený žlučník a žlučovody nečistotami v podobě žlučových kamenů a tzv. bahna, odráží se to nejen na trávicích obtížích, ale velmi často právě na celkové dysfunkci metabolismu v těle.</p>
<p>Žlučník není nutné operativně vyndávat. Nečistoty leze spolehlivě uvolnit <strong>správnou očistnou kůrou.</strong> Při očistné kůře se kameny a další nečistoty naruší užívanou solí a postupně se vyplaví do střev a stolicí ven.</p>
<p>Žlučové kameny v těle nejsou opravdu tvrdé kameny. Je to shluk cholesterolu, solí a kyselin. Ten dokáže pružnými žlučovými cestami do střeva dobře projít. Kameny úplně ztvrdnou až po vyloučení z těla.</p>
<p>Ukáži vám krok po kroku jak se zbavit žlučových kamenů ověřenou očistou, kterou sestavil lékař. Očista je zcela <strong>bezpečná a velmi účinná</strong>. Nechte se inspirovat lázeňskými procedurami a léčivou vodou z Karlových Varů</p>
<h2>Budete potřebovat:</h2>
<ul>
<li>200g prvotřídního panenského olivového oleje</li>
<li>250 g květu heřmánku</li>
<li>500 g lněného semínka</li>
<li>3 litry mléka</li>
<li><a href="https://serafinbyliny.cz/produkt/karlovarska-sul_647">karlovarskou sůl</a> vřídelní na vnitřní užití</li>
<li>3 dny volna</li>
</ul>
<h2>Den první</h2>
<p>Vstaneme v 5 hodin, vezmeme si 3 kávové lžičky karlovarské soli rozpuštěné ve vodě, vypijeme ¼ litru studené vody a udržujeme pohyb. Posnídáme kávu, mléko nebo čaj a suchý rohlík. (Při alergii na laktózu se používá bezlaktózové mléko nebo rostlinné mléko)</p>
<p>V poledne si opět vezmeme 3 kávové lžičky karlovarské soli a totéž co k snídani nebo větší množství nesolené a nemastné kaše z hrubé krupice.</p>
<p>Ve 13.45 ulehneme do tepla a ve 14.00 hodin přiložíme první teplý obklad z květů heřmánku ve dvou řídkých plátěných sáčcích. Obklady se střídají po deseti minutách a ohřívají se na pařáku. Bavlněné sáčky jsou velikosti cca 20 x 50 cm naplněné heřmánkem. Přikládají se na pravou stranu do krajiny jaterní tak, aby zasáhly pod pravým bokem i část zad. Obklady přikládáme asi 2 hodiny.</p>
<p>Odpoledne pijeme pouze vodu nebo čerstvé šťávy.</p>
<h2>Den druhý</h2>
<p>Vstaneme opět v 5 hodin a opakujeme to, co první den.</p>
<p>Před 12. hodinou sníme opět větší množství kaše z hrubé krupice (nesolit, nemastit, nesladit). V kašovité stolici začínají vycházet kamínky.</p>
<p>Ve 13.45 opět ulehneme do tepla a ve 14.00 hodin začneme dávat obklady z namletého lněného semínka uvařeného v mléce na hustou kaši, jejíž hustota se udržuje přiléváním mléka. Horká kaše se dává do sáčků a v nich se ohřívá na pařáku. Obklady se střídají po dvaceti minutách a přikládají se proti žlučníku zepředu a ležíme stále na pravém boku.</p>
<p>Obklady končí v 17.00 hodin. Potom vypijeme 1/3 z připraveného oleje a zůstáváme v klidu ležet na pravém boku bez mluvení a pohybu. Další třetina oleje se vypije v 17.30 a zbytek v 18.00 hodin. Pokud máte potíže s pitím oleje, můžete k tomu olizovat citron jako ochranu proti zvracení.</p>
<p>Potom je potřeba podložit si nohy tak, aby byly výš než hlava a stále ležíme na pravém boku v klidu bez mluvení alespoň 1 hodinu. V této době odchází kamínky bezbolestně do střev. Nesmí se jíst, pít, kouřit, nejlépe je usnout.</p>
<h2>Den třetí</h2>
<p>Vstaneme v 5.00 hodin, déle neležíme, vezmeme si 3 kávové lžičky karlovarské soli. Žlučové kamínky vycházejí z těla ven mezi 5. a 9. hodinou. Jsou měkké, zelené barvy, potažené zelenou blankou. V průběhu léčby nevycházíme ven, používáme kbelík a vodu, aby mohla být stolice oddělena. Kamínky většinou plavou na povrchu, protože jsou nasáklé olejem. Pokud se stolice nedostaví, je nutno použít klystýr.</p>
<p>Po vyjití kamínků z těla je možno pít a jíst vše bez obav.</p>
<p>Kúra se může za rok opakovat.</p>
<p><strong>Před nasazením této očistné kúry je vhodné 7-10 dní pít bylinný čaj <a href="https://serafinbyliny.cz/produkt/cisty-zlucnik-porcovany-caj_411">Čistý žlučník</a> </strong><strong>a k tomu užívat tinkturu z pupenů <a href="https://serafinbyliny.cz/produkt/ostropestrec-tinktura-z-pupenu_184">Ostropestřec</a></strong></p>
<p>Tuto očistnou kůru používám u svých klientů již dvacet let, a to s velkými úspěchy. Kamínky na obrázku jsou od jednoho z nich.</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2020/02/žlučové-kameny.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$draft$q$,$q$2022-03-14T12:43:37+00:00$q$,$q$https://anetabenediktova.cz/702-2/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$streva-a-nase-emoce$q$,$q$Střeva a naše emoce$q$,$q$Zažili jste někdy pocit, že po dobrém jídle jste měli v žaludku jak v „pokojíčku“ a celé tělo vám zaplavil příjemný pocit uvolnění a blaha? Stane se to ve chvíli, kdy jíte pomalu a vědomě, tedy ne ve spěchu a na talíři máte odpovídající množství jídla ve skladbě, která dělá vašemu tělu dobře. A co j$q$,$q$<p>Zažili jste někdy pocit, že <strong>po dobrém jídle</strong> jste měli v žaludku jak <strong>v „pokojíčku“</strong> a celé tělo vám zaplavil příjemný <strong>pocit uvolnění a blaha?</strong></p>
<p>Stane se to ve chvíli, <strong>kdy jíte pomalu a vědomě,</strong> tedy ne ve spěchu a na talíři máte odpovídající množství jídla ve skladbě, která dělá vašemu tělu dobře. A co je důležité, <strong>jídlo má teplotu těla.</strong></p>
<p>Potom, pokud váš zažívací trakt není přeplněný a nenachází se v něm jen přepálené tuky a nadmíra cukrů, můžete tento pocit zažít. Pocit příjemného blaha.</p>
<h2>Proč tomu tak je?</h2>
<p>Vše, co prochází naším střevem potřebuje ke svému strávení enzymy, žluč a další látky, které štěpí jednotlivé složky potravy. Co je potřeba v danou chvíli udělat, či uvolnit řídí tzv. enterogenní nervová soustava ve střevech neboli ve zkratce ENS. Můžeme si jí představit jako síť milionů nervových buněk v našem střevě.</p>
<p><strong>Tato rozsáhlá nervová síť je propojena s trávicími orgány , ale také přímo s mozkem.</strong> Co se týče komunikace mezi ENS a mozkem, tak bylo zjištěno, že z celkového objemu vzruchů probíhajících mezi těmito dvěma orgány probíhají většinou signály <strong>ve směru od střev k hlavě</strong> a v malé menšině od hlavy do střev.</p>
<blockquote>
<p>Takže to, co se děje ve střevech ovlivňuje naše myšlení víc, než ovlivňuje přímo naše myšlení střeva.</p>
</blockquote>
<h3>Pohoda a klid ve střevech se projevuje celkovou uvolněností a spokojeností.</h3>
<p>Typickým příkladem je situace, kdy nám<strong> klesne hladina cukru</strong>. Agrese, nepatřičné poznámky, nervozita.</p>
<p>Kolik agrese bylo vypuštěno z úst po velkém přejedení se nebo naopak po příliš dlouhém hladovění?</p>
<p>Je jisté, že naše pocity a z nich vyvěrající myšlenky jsou ovlivňovány spokojeností našeho břicha.</p>
<h2>Co máme ve střevech</h2>
<p>Ne všichni obyvatelé střev jsou vítaní nájemníci. Přemnožené <strong>plísně</strong> například vedou k nutkavé chuti na <strong>sladké</strong> a k trvalé <strong>podrážděnosti a únavě. </strong>Způsobují i <strong>chronické záněty a poruchy imunity</strong></p>
<p>Škrkavky, tasemnice, hlísti nebo roupi vypouštějí neurotoxiny, které v CNS spouští <strong>neklid, úzkost a depresi.</strong> Pokud se necítíme dobře, hraje v tom hlavní roli naše břicho.</p>
<blockquote>
<p>Při poklesech nálad je proto správné soustředit se na střeva, protože tam se koneckonců tvoří většina hormonu serotoninu, který je zodpovědný za naši dobrou náladu.</p>
</blockquote>
<h2>Co tedy dělat pro spokojené signály z našich střev?</h2>
<p>Pokud si přejeme vystěhovat ze svých střev všechny příživníky a parazity, jezme hodně pestrobarevné zeleniny, čerstvých bylinek a kvašených výrobků, pijme zásadně neslazené nápoje.</p>
<p>Vyšleme do našich střev silné pomocníky – <strong>přírodní houby</strong>. Ty umí zatočit s parazity, plísněmi i dalšími nezvanými hosty.</p>
<p>Poslouchejte <strong>signály svých střev.</strong> Tyto nám střeva dávají prostřednictvím rozsáhlé nervové sítě zvané <strong>druhý mozek.</strong> Jsou to zprávy nezkreslené našimi domněnkami, a pokud je nám z něčeho na nic, měli bychom jít od toho. Ať už je to jídlo, nebo setkání.</p>
<p><strong>Známým je efekt pročištění mysli jako následek pročištění střev.</strong> Mezi jogíny je tento způsob očisty známý jako šankhaprakšálana. Vyčištění střev a mysli se v tomto případě dosahuje pitím slané vody kombinovaným s cvičením.</p>
<p>Nemusíme chodit až do daleké Indie. Střeva můžeme pročistit i méně dramatickým způsobem. Vyzkoušejte kombinaci přípravků <a href="https://serafinbyliny.cz/produkt/paravit_125">Paravit</a> + <a href="https://serafinbyliny.cz/produkt/cytosan_614">Cytosan.</a> Doporučujeme užívat ráno na lačno 2 kapsle Antiparazitenu a večer před spaním 2 kapsle Cytosanu. Důležité je při této  kůře doplnit kvalitní probiotika ve formě <a href="https://serafinbylinky.harmonelo.video/">Harmonelo Probio</a> ráno na lačno.</p>
<p>Celá kůry by měla trvat tři měsíce, vždy s týdenní pauzou po jednom měsíci.</p>
<p>Věřím, že sami pocítíte skvělý účinek pročištění trávicího traktu na vaši duševní pohodu a klid.</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2022/03/streva-a-emoce.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-03-07T09:03:08+00:00$q$,$q$https://anetabenediktova.cz/streva-a-nase-emoce/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$jarni-unava-a-bylinky$q$,$q$Jarní únava a bylinky$q$,$q$Nejčastěji skloňovaným tématem v jarních měsících bývá „jarní únava“. Co to vlastně je a co jí způsobuje z pohledu přírodní medicíny? A také co s ní dělat? Fyzická oblast První oblastí našeho těla, která se podílí na vzniku jarní únavy je trávení a s ním spojená játra V zimních měsících intuitivně d$q$,$q$<p>Nejčastěji skloňovaným tématem v jarních měsících bývá „jarní únava“. Co to vlastně je a co jí způsobuje z pohledu přírodní medicíny? A také co s ní dělat?</p>
<h2>Fyzická oblast</h2>
<p>První oblastí našeho těla, která se podílí na vzniku jarní únavy je <strong>trávení </strong>a s ním spojená<strong> játra</strong></p>
<p>V zimních měsících intuitivně dáváme přednost tzv. jangovým potravinám, tedy zahřívacím potravinám. Je to zejména jídlo s vyšším obsahem tuků a cukrů. Tato strava nám zajišťuje určitou izolaci a rovnoměrné rozložení energie pro zahřátí organismu. V zimních měsících <strong>často také trošku přibereme</strong>, což je přirozené.</p>
<p>Tento typ stravy však většinou s sebou přináší <strong>zanesení střev</strong> nestrávenými zbytky, <strong>přetížení jater</strong> a trávicího traktu tučnými a sladkými potravinami.</p>
<h2>Biologické cykly</h2>
<p>Moderní doba se všemi svými vymoženostmi, ale také s vysokým tlakem na velký pracovní výkon, narušuje naše přirozené biologické cykly.</p>
<p><strong>V zimě příroda odpočívá</strong>, funguje v klidovém režimu.<strong> I my bychom se měli takto chovat.</strong></p>
<p>Místo toho pracujeme jako v létě, prodlužujeme si dny dlouhým svícením, přetápíme svá obydlí, snažíme se dělat činnosti jako ve vrcholném létě. Tělo tím ztrácí své přirozené biologické cykly, nemá možnost odpočinku, regenerace a začíná být unavené. Nejvíce za to platíme na jaře, kdy je celý organismus z náročné zimy vyčerpaný.</p>
<h2>Psychická rovina</h2>
<p>Na zimní období připadají vánoční svátky, které velmi silně ovlivňují naše emoce. U některých osob vyvolávají sklony k melancholii a depresím.</p>
<p>Zimní nedostatek světla působí na tvorbu našich <strong>„hormonů dobré nálady“. </strong>Čím méně světla, tím méně hormonů, a tím horší nálada.</p>
<p>Nedostatek slunečního svitu a &#8222;těžká&#8220; strava způsobují to, že nám začnou chybět vitamíny zejména vit. D a také minerály a enzymy.</p>
<p><img fetchpriority="high" src="https://anetabenediktova.cz/wp-content/uploads/2020/03/sedmikráska-jídlo-300x200.jpg" alt="" /></p>

<h2>Co s tím?</h2>
<h3>Odlehčená strava</h3>
<p>V jarním období je velmi vhodné <strong>zařazovat lehké půsty, snížit příjem tuků</strong>, zaměřit se na zelené saláty plné jarní svěží energie.</p>
<h3>Bylinky pomáhají</h3>
<p>Při prvním jarním sluníčku určitě narazíte na mladé <strong>květy sedmikrásky</strong>. Ty můžete rovnou utrhnout a sníst a nebo si z nich uvařte bylinný čaj. Ten umí podpořit očistu jater a žlučníku a také bude pozitivně působit na <strong>vaši pleť</strong>. S odvarem ze sedmikrásky si můžete každé ráno omývat obličej. Vždyť sedmikráska, to je sedm krás!</p>
<p>V <strong>březových pupenech</strong> najdete hodně síly, energie a očistných látek, které pomohou <strong>překonat jarní únavu.</strong> Pupeny z břízy můžete konzumovat rovnou nebo ve formě <a href="https://serafinbyliny.cz/produkt/briza-tinktura-z-pupenu_149">tinktury</a> z pupenů. Pokud je ve vašem těle hodně odpadních látek, tak bříza je dokáže rychle dostat ven, což můžete zaznamenat na své kůži.</p>
<p><strong>Mladé kopřivy</strong> jsou první jarní bylinka, kterou najdeme na mezích či rumištích. Po natrhání jí převaříme jednu minutu a pak po deseti minutách luhování slijeme. Tento nápoj pijeme 2x denně na lačno, nejdéle však deset dní. <a href="https://serafinbyliny.cz/produkt/kopriva-tinktura-z-pupenu_174">Kopřiva</a> čistí krev, játra a střeva a má silné protialergické účinky. Jak na časné jarní alergie najdete <a href="https://anetabenediktova.cz/jarni-alergie-a-jejich-lecba-bylinami/">zde</a></p>
<p>Máte rádi chutné čaje? Zkuste bylinný čaj <a href="https://serafinbyliny.cz/produkt/restart_467">Restart</a>. Obsahuje skvělé olivové listí v Bio kvalitě. Žádný strom není tak úzce spojen s rozvojem lidské civilizace jako <strong>Olivovník.</strong></p>
<p>Větvičky z olivovníků se používaly při různých obřadech, olivy jako potravina, olivový olej nejenom do kuchyně, ale také jako přírodní léčivo.</p>
<p>Méně známé je používání<strong> olivových listů</strong>. V listech Olivovníku evropského se nachází látka Oleuropein. Ten je velmi silným antioxidantem. Pomáhá čistit játra, střeva i cévy, upravuje krevní tlak, hladinu cholesterolu v krvi a velmi silně<strong> působí proti únavě, zejména té jarní</strong></p>
<h3>Pohyb venku</h3>
<p>Pohyb venku, hluboké dechy, pozorování jarní přírody, poslouchání zpěvu ptáků, to vše navozuje  příjemné pocity pro naše tělo a tvorbu dostatečného množství „hormonů dobré nálady“.</p>
<p>Je to jeden z velmi účinných nástrojů, jak předcházet jarní únavě.</p>
<p><strong>Teď si už můžete užít krásné jaro bez jarní únavy!</strong></p>

<blockquote>
<h4>Můj tip na kúru proti jarní únavě: čaj Restart + kapsle Multiserafin + tinktura z pupenů Břízy</h4>
<p>vše najdete na<a href="https://serafinbyliny.cz/"> www.serafinbyliny.cz</a></p></blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/03/relax.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2022-03-07T08:23:07+00:00$q$,$q$https://anetabenediktova.cz/jarni-unava-a-bylinky/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$jarni-alergie-a-jejich-lecba-bylinami$q$,$q$Jarní alergie a jejich léčba bylinami$q$,$q$Také to znáte? Vodnatá rýma, svědění a pálení sliznic, zánět čelních dutin, zarudlé oči. To jsou jen některé ze známých a velmi obtěžujících projevů jarních alergií. Často nacházíme ještě zbytky sněhu na polích a my již trpíme některými z příznaků. Příčinou mohou být třeba časně kvetoucí jívy nebo b$q$,$q$<p>Také to znáte? Vodnatá rýma, svědění a pálení sliznic, zánět čelních dutin, zarudlé oči. To jsou jen některé ze známých a velmi obtěžujících projevů jarních alergií. Často nacházíme ještě zbytky sněhu na polích a my již trpíme některými z příznaků. Příčinou mohou být třeba časně kvetoucí jívy nebo břízy.</p>
<h3><strong>Co je to alergie</strong></h3>
<p>Alergie je definována jako nepřiměřená odpověď našeho imunitního systému na běžné látky z okolního prostředí, které by nám neměly vadit – ale vadí. Tato látka se označuje jako alergen a aktivuje protilátky ze skupiny imunoglobulinu IgG. Dochází k jejich zvýšené tvorbě, což spustí některou z alergických reakcí. Ta může být banální, ale v některých případech může být i život ohrožující.</p>
<h3><strong>Jak alergie vzniká</strong></h3>
<p>Klasická medicína většinou uvádí, že důvody a vznik alergií není přesně znám. Z pohledu přírodní medicíny pracujeme s tím, že základem alergií jsou <strong>problémy ve střevech, a také v játrech</strong>. Střevní výstelku tvoří miliarda buněk epitelu, který vytváří bariéru mezi vnějším prostředím a vnitřním prostředím střeva. Střevo je domovem triliónů bakterií, které hrají důležitou roli nejenom při štěpení živin, ale hlavně ovlivňují efektivnost fungování našeho imunitního systému.</p>
<blockquote>
<p>Jemnou výstelku střev lze velmi jednoduše poškodit. Nejčastějšími viníky bývají <strong>alkohol, antibiotika, analgetika a jiné léky.</strong> Silně se na jejím poškozování projevuje dlouhodobý <strong>chronický stres.</strong> Významným faktorem je přílišná konzumace <strong>lepku, přidaného cukru a kravského mléka.</strong> Všechny tyto složky potravy mají velmi silný alergenní potenciál a také systematicky poškozují střevní epitel. Ten se následně mírně rozestupuje a vznikne situace, kdy bariéra mezi vnitřním prostředím střeva a zevním prostředím těla začíná být „děravá“. Potom se nám do těla začínají dostávat viry, bakterie, plísně a špatně strávené části potravy. Tomuto stavu se také říká<strong> „syndrom zvýšené propustnosti střev“.</strong></p>
</blockquote>
<p>Některé špatně strávené bílkoviny z naší stravy, které se normálně v trávicím taktu štěpí na základní částice – aminokyseliny, procházejí takto poškozenou střevní stěnou přímo do krevního řečiště. Tam je imunitní systém identifikuje jako cizorodou látku a napadne je. Takto vznikají potravinové alergie, ale celá řada jiných typů alergií jako třeba na pyly, trávy či zvířecí srst.</p>
<h3><strong>Jarní alergie a jejich projevy</strong></h3>
<p>K nejběžnějším typům alergií patří právě časné jarní alergie. Podle počasí mohou vznikat již koncem února nebo hned začátkem března. Pokud je zima mírná a příroda se začíná brzy probouzet, tak pyly poletují v ovzduší již v únoru. Lidé si pak často pletou alergické projevy s nachlazením. Nejčastějším projevem mimo vodnaté rýmy bývá bolest hlavy v oblasti čela a tlak za očima. To je způsobené alergickým zánětem sliznic vedlejších nosních a čelních dutin, které reagují právě na polétající pyly v ovzduší.</p>
<p><img src="https://anetabenediktova.cz/wp-content/uploads/2021/02/Perilla-1024x678.jpg" alt="" /></p>
<h3><strong>Přírodní léčba</strong></h3>
<p>Z pohledu přírodní medicíny je možné alergie postupně léčit, ale jedná se o dlouhodobý proces. Obecně platí, že pokud chceme mít mírnější projevy časných jarních alergií, tak je potřeba přírodní přípravky nasadit už v zimním období nebo co nejdříve na jaře.</p>
<h3><strong>Byliny i houby pomáhají</strong></h3>
<p><strong>Žampion mandlový</strong> – přírodní houba, která účinně posiluje fungování imunitního systému. Používá se při alergiích, astmatu, chronických zánětech průdušek. Snižuje kašel, zlepšuje stav pokožky a celkové fungování jater.</p>
<p><strong>Rdesno mnohokvěté</strong> – popínavá bylina, která účinně regeneruje játra a zlepšuje stav a činnost střev. Tímto působením podporuje imunitu a snižuje alergické projevy u různých druhů alergií.  Rdesno mnohokvěté má mimo jiné i protizánětlivé účinky, upravuje hladinu cukru a tuků v krvi</p>
<p><strong>Perilla křovitá</strong> – krásná, barevná bylina, která velmi dobře působí při alergiích, vlhkém chronickém kašli a astmatu. Obsažené látky (např. alfa-pinen, apigenin, beta-sitosterol, karyophyllen, myristicin, fenylpropanoid) se zapojují do anti-alergenních a protizánětlivých procesů a ukazují na možnost využití v léčbě astmatu, sezónních alergií a chronických bronchitid. Bylina vykazuje i silně antiparazitální účinky.</p>
<blockquote>
<p>Obě byliny i houbu můžeme užívat zároveň, ideálně třeba v jedné kapsli &#8211; <a href="https://www.serafinbyliny.cz/produkty-pylergen-prirodni-kapsle-detail-1258">Pylergen</a></p>
</blockquote>
<p><strong>Černý rybíz</strong> – pokud nasbíráme jeho pupeny a správným způsobem naložíme, tak <a href="https://serafinbyliny.cz/produkt/cerny-rybiz-tinktura-z-pupenu_154">vzniklá tinktura</a> nám může hodně pomoci při zvládání alergií. Pupeny Černého rybízu nám v těle vyvolají obdobnou reakci jako užití chemických anti alergik, nicméně pupeny to vyvolají přirozenou cestou.</p>
<p>Při přírodní léčbě alergií musíme mít trpělivost. Často trvá několik měsíců, než se alergie přestanou silně projevovat, nicméně během krátké chvíle po nasazení přírodní léčby úlevu zcela jistě pocítíme.</p>
<p>Velmi důležité při léčbě alergií je působit na střeva a tím na funkci imunitního systému, která se střevy souvisí a způsobuje právě alergické reakce. Pokud chceme, aby přírodní léčba byla účinná, tak zde hraje zásadní roli strava. Vynechání přidaného cukru z potravy, kravského mléka, alkoholu a bílé mouky celkovou léčbu zefektivní a urychlí. Nezapomeňte posílit mikrobiom střeva. Skvělé zkušenosti mám s přípravkem <a href="https://serafinbylinky.harmonelo.video/">Harmonelo vitality</a></p>
<p>Věřím, že toto jaro se budete moci v klidu nadechnout s čistým nosem i srdcem.</p>
<blockquote>
<p><strong>Tip:</strong> pokud trpíte časnou jarní alergií, ale i letními alergiemi, tak již nyní začněte užívat kůru</p>
<p><strong> čaj <a href="https://serafinbyliny.cz/produkt/pylergen-sypany-caj_219">Pylergen</a> + kapsle <a href="https://www.serafinbyliny.cz/produkty-pylergen-prirodni-kapsle-detail-1258">Pylergen</a> + tinktura z pupenů <a href="https://serafinbyliny.cz/produkt/cerny-rybiz-tinktura-z-pupenu_154">Černý rybíz</a> + Harmonelo <a href="https://serafinbylinky.harmonelo.video/">Vitality</a></strong></p>
<p>Kůru užívejte 2 měsíce s týdenní pauzou po jednom měsíci. Následně zůstaňte přes alergenní období na kapslích Pylergen a Harmonelu.</p>
<p>
